DECLARE
  c jsonb := $cj$[{"title":"Домик изумрудного цвета","full_story":"Реставратор получает заказ: разобрать под снос старый домик в городке его детства — тот самый, изумрудный, которому он мальчишкой молился из окна спальни. Бригада ждёт, а он до темноты сидит напротив и не может поднять руку. Ночью он снимает с крыльца бумажный фонарик, вешает его у себя над столом и подписывает акт как последний жилец.","hero_pov":"Реставратор, приехавший сносить дом своего детства","central_conflict":"Платный заказ требует разобрать дом, который для героя — единственное доказательство чуда в жизни.","emotional_arc":"От служебного равнодушия к детскому трепету и решимости сохранить","ending_direction":"Поворот: он не спасает дом — он забирает его свет и становится хранителем","hook_direction":"Изумрудный, гори во мне","genres":["Синтвейв","Эмбиент"],"moods":["Нежность","Светлая грусть"],"energy":"Высокая","themes":["дорога","детство"],"generator_brief":"Тёплый синти-поп с аналоговой подкладкой и колокольчиками; куплеты — дорога к сносу, припев — детство, светящееся зелёным.","generator_story":"Реставратор приезжает сносить зелёный домик, которому молился в детстве, и не поднимает руку: он забирает лишь бумажный фонарик с крыльца, чтобы дом остался жить в нём.","primary_genre":"Синтвейв","primary_mood":"Нежность","primary_theme":"дорога","story_shelf":"Трагические истории","conflict_key":"заказ-на-снос-против-детской-молитвы","image_key":"фонарик-на-крыльце-изумрудного-домика","turn_key":"свет-дома-переезжает-к-хранителю","hook_key":"изумрудный-гори-во-мне","sort_order":"1402","original_key":"arsenij-tarkovskij|byl-domik-v-tri-okonca","author_name":"Арсений Тарковский","original_title":"Был домик в три оконца","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/arsenij-tarkovskij-byl-domik-v-tri-okonca/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1986.","music_adaptations":[],"source_synopsis":"Герой вспоминает домик детства необыкновенного зелёного цвета, которого нет даже в спектре радуги, — ребёнок верил, что тот перенёсся из рая. Днём в доме звучали игра и пение, а ночью на крыльце прощались и зажигали свечи в бумажных фонарях. Изумрудное чудо стоит перед глазами и у взрослого человека.","main_image":"бумажные фонарики на крыльце изумрудного домика"},{"title":"Не в тот день","full_story":"Бариста Ярослав всю жизнь путает дни: свидание, назначенное на вторник, он честно простоял в четверг, а в их настоящий вторник шёл дождь и никого не было. Через месяц она сама находит его в кофейне под ливнем, молча ставит мокрый зонт к его сухому и говорит, что тоже перепутала. Они решают больше не сверяться с календарём.","hero_pov":"Бариста, который всегда ждёт не в тот день","central_conflict":"Он готов простоять в ожидании хоть год, но календарь каждый раз крадёт у него день встречи.","emotional_arc":"От безнадёжной пунктуальности к принятию чужого «вчера»","ending_direction":"Поворот: опоздание оказывается общим, и дождь становится первым свиданием","hook_direction":"Приходи хотя бы сегодня","genres":["Блюз","Джаз"],"moods":["Уязвимость","Нежность"],"energy":"Низкая","themes":["прощение","любовь"],"generator_brief":"Медленный ночной блюз с вибрато-гитарой и щётками; куплет — пустая остановка, припев — дождь на двоих.","generator_story":"Бариста перепутал день свидания и простоял его зря, а девушка пришла в другой день под дождём; она ставит свой мокрый зонт к его сухому, и опоздание становится первым настоящим свиданием.","primary_genre":"Блюз","primary_mood":"Уязвимость","primary_theme":"прощение","story_shelf":"Любовные сцены","conflict_key":"перепутанный-календарь-против-ожидания","image_key":"мокрый-зонт-у-сухого","turn_key":"опоздание-становится-свиданием","hook_key":"приходи-хотя-бы-сегодня","sort_order":"1403","original_key":"arsenij-tarkovskij|s-utra-ya-tebya-dozhdalsya-vchera","author_name":"Арсений Тарковский","original_title":"С утра я тебя дожидался вчера","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/arsenij-tarkovskij-s-utra-ya-tebya-dozhidalsya-vchera/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1986.","music_adaptations":[],"source_synopsis":"Герой ждёт любимую, но времена года в его рассказе перепутаны: он ждал её в тот солнечный день, когда она не пришла, а встретил её в другой, пасмурный, под дождём. Сияющий день так и остался пустым, а настоящая встреча вышла холодной и тёмной. Тоска уже не унимается ничем.","main_image":"два зонтика над мокрой остановкой"},{"title":"Ночной сонник предков","full_story":"Ночной таксист Геннадий из любопытства сдаёт ДНК-тест, и следующую смену ему снится суд: тени прабабушек в старых платках разбирают по древним законам каждый его разворот и каждую невысказанную нежность. Он просыпается на обочине, где за окном стоят в тумане коровы и бесконечно, спокойно жуют. Геннадий впервые за годы выспался: приговор отменён рассветом.","hero_pov":"Ночной таксист под судом прабабушек","central_conflict":"Предки требуют отчёта за каждый прожитый день, а герой устал оправдываться даже во сне.","emotional_arc":"От ночного страха суда к спокойному приятию своей древней природы","ending_direction":"Поворот: вердикт не нужен — время само всё пережёвывает и прощает","hook_direction":"Все мы из одной пещеры","genres":["Техно","Эмбиент"],"moods":["Освобождение","Тревога"],"energy":"Средняя","themes":["Ночь","память"],"generator_brief":"Гипнотическое техно с шумом ночного двигателя; куплет — голоса предков нарезкой, припев — широкое примирение.","generator_story":"Ночной таксист сдаёт ДНК-тест, и во сне тени предков судят его за каждый прожитый день; на рассветной обочине он видит коров, спокойно жующих время, и впервые отменяет себе приговор.","primary_genre":"Техно","primary_mood":"Освобождение","primary_theme":"Ночь","story_shelf":"Люди и животные","conflict_key":"суд-предков-против-усталости","image_key":"коровы-жующие-время-у-дороги","turn_key":"вердикт-отменяется-рассветом","hook_key":"все-мы-из-одной-пещеры","sort_order":"1404","original_key":"arsenij-tarkovskij|sny","author_name":"Арсений Тарковский","original_title":"Сны","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/arsenij-tarkovskij-sny/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1986.","music_adaptations":[],"source_synopsis":"Ночь у Тарковского — как жрец с древним сонником: во сне человек поднимается по ступеням над пустотой, и тени устраивают ему суд, хотя все люди вышли из одной пещеры и пишут одними знаками. Каждый обязан пройти свой путь яви и передать увиденное детям. В финале герой находит приют на чужом пороге, а у дороги спокойно пасутся огромные быки, пережёвывающие время.","main_image":"быки у ночной дороги, пережёвывающие время"},{"title":"Билеты на ноябрь","full_story":"Супруги после тридцати лет брака сдают на вокзале в камеру хранения настоящий чемодан, в который сложили накопленные обиды и невысказанные претензии, — и берут два билета в ноябрьский город, где познакомились. Пустые аллеи, вороньи гнёзда, столько неба, что не видно людей. На последней скамейке парка они признаются друг другу, что всю жизнь зря береглись, и решают вернуться сюда каждую осень.","hero_pov":"Муж из пары, сдавшей обиды в камеру хранения","central_conflict":"Тридцать лет осторожности против одной поездки, которая может всё вернуть — или окончательно сломать.","emotional_arc":"От усталой привычки к вольному ноябрьскому счастью","ending_direction":"Поворот: беречься отменено — обиды остались в ячейке, а они уехали лёгкими","hook_direction":"Оставь года на вокзале","genres":["EDM","Синтвейв"],"moods":["Освобождение","Надежда"],"energy":"Высокая","themes":["дорога","город"],"generator_brief":"Светлый EDM-гимн с широкими падами и поездным ритмом; куплеты — сборы, припев — открытое ноябрьское небо.","generator_story":"Супруги сдают в камеру хранения чемодан, куда сложили тридцать лет обид, и едут в пустой ноябрьский город своей молодости; там они решают больше никогда не беречься друг от друга.","primary_genre":"EDM","primary_mood":"Освобождение","primary_theme":"дорога","story_shelf":"Любовные сцены","conflict_key":"чемодан-обид-против-поездки","image_key":"пустой-ноябрьский-город-вдвоём","turn_key":"беречься-отменено","hook_key":"оставь-года-на-вокзале","sort_order":"1405","original_key":"david-samojlov|davaj-poedem-v-gorod","author_name":"Давид Самойлов","original_title":"Давай поедем в город","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/david-samojlov-davaj-poedem-v-gorod/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1990.","music_adaptations":[],"source_synopsis":"Герой зовёт близкого человека уехать в город их молодости, оставив прожитые годы на вокзале, как чемоданы. Поздней осенью город почти пуст, неба больше, чем людей, мороз скрепил всё зыбкое, что раньше разваливалось. В финале герой понимает, зачем живёт, и клянётся себе больше не беречь себя и не гасить страсти.","main_image":"чемоданы старых лет, сданные в камеру хранения"},{"title":"Неделя молчания и дуэт","full_story":"Джазмен Стас возвращается под утро с ток-сессии, счастливый и помятый, с мелодией в голове, — и жена объявляет ему неделю молчания: ни завтраков, ни смешинок, ни «как прошёл день». Третий день он мается, а на четвёртый пишет за ночь дуэт для их старых инструментов — скрипки и альта. На седьмое утро она молча ставит ноты на пюпитр и берёт альт.","hero_pov":"Джазмен под домашним приговором","central_conflict":"Дома он должен каяться, а из его вины уже растёт лучшая мелодия года.","emotional_arc":"От виноватой бодрости через ледяную неделю к дуэту вдвоём","ending_direction":"Поворот: наказание кончается не примирением словами, а общей музыкой","hook_direction":"Но зато дуэт","genres":["Джаз","Блюз"],"moods":["Эйфория","Ирония"],"energy":"Высокая","themes":["Выбор","музыка"],"generator_brief":"Солнечный свинг с лёгким хонки-тонком и струнными; куплет — крадущийся герой, припев — мелодия побеждает обиду.","generator_story":"Джазмен возвращается под утро с сессии, и жена объявляет ему неделю ледяного молчания; он пишет за ночь дуэт для их скрипки и альта, и на седьмое утро она молча ставит ноты на пюпитр.","primary_genre":"Джаз","primary_mood":"Эйфория","primary_theme":"Выбор","story_shelf":"Юмор: семейные драмы","conflict_key":"выговор-жены-против-музыки","image_key":"ноты-на-пюпитре-жены","turn_key":"наказание-кончается-дуэтом","hook_key":"но-зато-дуэт","sort_order":"1406","original_key":"david-samojlov|duet-dlya-skripki-i-alta","author_name":"Давид Самойлов","original_title":"Дуэт для скрипки и альта","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/david-samojlov-duet-dlya-skripki-i-alta/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1990.","music_adaptations":[],"source_synopsis":"Лёгкая сценка из жизни Моцарта: весёлый и слегка хмельный гений возвращается домой с пирушки, любуясь улицей и людьми. Дома его ждёт строгая жена и неделя ледяного молчания — ни слова, ни улыбки. Но под утро в кармане уже готов новый дуэт для скрипки и альта, и герой готов платить за свои праздники этой ценой: вознаграждение — бессмертная музыка.","main_image":"ноты на пюпитре жены"},{"title":"Классика из репродуктора","full_story":"На захолустном вокзале среди ночи из треснувшего репродуктора вместо прогноза погоды вдруг начинает звучать классическая поэзия. Двое ожидающих пересадки — настройщик роялей и девушка-проводница — сначала смеются, потом замолкают и слушают, стоя у колонки. Их поезда уходят один за другим, а они всё стоят: у них впервые за годы появляется разговор длиной в целую жизнь, и последний поезд они пропускают нарочно.","hero_pov":"Настройщик роялей, слушающий колонку вместо объявления","central_conflict":"Расписание требует разъехаться по своим путям, а общий голос из колонки впервые за годы требует остаться.","emotional_arc":"От усталого ожидания к вольному отказу от расписания","ending_direction":"Поворот: они пропускают свои поезда — и не считают это потерей","hook_direction":"Читайте, не переключайте","genres":["EDM","Электропоп"],"moods":["Вдохновение","Романтика"],"energy":"Высокая","themes":["Выбор","голос"],"generator_brief":"Электропоп с радиошумом и нарастающим светом; куплеты — гул перрона, припев — чистый голос сквозь помехи.","generator_story":"На ночном вокзале из сломанной трансляции вместо сводок гремит классическая поэзия; настройщик и проводница слушают её у колонки и нарочно пропускают свои поезда ради первого настоящего разговора.","primary_genre":"EDM","primary_mood":"Вдохновение","primary_theme":"Выбор","story_shelf":"Любовные сцены","conflict_key":"расписание-против-голоса-из-колонки","image_key":"двое-у-треснувшего-репродуктора","turn_key":"поезда-пропущены-нарочно","hook_key":"читайте-не-переключайте","sort_order":"1407","original_key":"david-samojlov|pushkin-po-radio","author_name":"Давид Самойлов","original_title":"Пушкин по радио","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/david-samojlov-pushkin-po-radio/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1990.","music_adaptations":[],"source_synopsis":"Молодой солдат на разрушенном вокзале слышит из репродуктора хриплым голосом классическую поэзию — посреди торга, суеты и военных составов. Он знакомится с двумя девчонками, и высокие старые строки о юности и любви иронично ложатся на их флирт. Финал горек: налёт, взрывы, вокзала больше нет, а строки о тающих забавах юности звучат как пророчество.","main_image":"репродуктор с классикой над пустым перроном"},{"title":"Шары для лётчиков","full_story":"На празднике маленького аэроклуба в день памяти погибших лётчиков дети выпускают в небо сотню воздушных шаров. Молодой инструктор хочет пошутить про потерянные шарики, но старый механик Фомич останавливает его: ни один шар не пропадает — каждый долетает до своего адресата и ложится там цветами. К вечеру небо чистое, а на ладони у Фомича — обрывок нитки, как адрес отправки.","hero_pov":"Старый механик аэроклуба, знающий адрес шаров","central_conflict":"Праздник хочет смеяться, а память в этом же небе требует тишины и доставки.","emotional_arc":"От детской ярмарки к взрослой памяти и обратно к светлому небу","ending_direction":"Поворот: шары не пропали — они дошли, и небо стало почтой памяти","hook_direction":"Долетят до своих","genres":["Драм-н-бейс","Эпик-рок"],"moods":["Светлая грусть","Вдохновение"],"energy":"Высокая","themes":["Свобода","память"],"generator_brief":"Драм-н-бейс с парящими струнными и брейками; куплеты — разбег детей, припев — шары уходят вверх и доставляют память.","generator_story":"На празднике аэроклуба в память о погибших лётчиках дети выпускают сотню шаров; старый механик уверен, что ни один не пропадёт — каждый долетит до своего адресата и ляжет там цветами.","primary_genre":"Драм-н-бейс","primary_mood":"Светлая грусть","primary_theme":"Свобода","story_shelf":"Трагические истории","conflict_key":"детская-ярмарка-против-памяти-неба","image_key":"шары-над-аэродромом-памяти","turn_key":"шар-доходит-до-адресата","hook_key":"долетят-до-своих","sort_order":"1408","original_key":"boris-sluckij|sudba-detskix-vozdushnyx-sharov","author_name":"Борис Слуцкий","original_title":"Судьба детских воздушных шаров","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/boris-sluckij-sudba-detskix-vozdushnyx-sharov/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1986.","music_adaptations":[],"source_synopsis":"Шары, сорвавшиеся с ниток детских рук, не исчезают: поэт уверен, что все они добираются до погибших в небе военных лётчиков и лежат там вместо цветов. Детская радость, улетевшая вверх, становится подарком тем, кто сгорел в воздушных боях. Сквозь лёгкий образ проступает щемящая память о целом поколении неба.","main_image":"шары, уходящие в небо над аэродромом"},{"title":"Открытка со списком вещей","full_story":"Комендантша общежития при закрывающемся заводе Мария Викторовна находит в почтовом ящике открытку с перечнем вещей, которые разрешено взять с собой при выселении, и датой явки. Она запирает дверь изнутри, не открывает никому, живёт без света и почти без звука всю зиму, пока вокруг идёт повальная выписка. Весной она мирно сдаёт комнаты заочникам, а открытку прячет за фотографию отца — там нет ничего страшного, только список из трёх слов.","hero_pov":"Комендантша, отказавшаяся выходить из комнаты","central_conflict":"Бумажка приказывает собрать жизнь в три вещи, а героиня отвечает тишиной и запертой дверью.","emotional_arc":"От испуга к тихому упрямству и живучести","ending_direction":"Поворот: повестка осталась бумажкой — комната пережила зиму и снова полна жильцов","hook_direction":"Из комнаты не выйду","genres":["Панк","Техно"],"moods":["Протест","Тревога"],"energy":"Взрывная","themes":["Выбор","дом"],"generator_brief":"Жёсткий панк с рваным ритмом и глухим басом; куплеты — шёпот за дверью, припев — отказ, повторённый как заклинание.","generator_story":"Комендантша общежития получает открытку с перечнем вещей к выселению и отвечает тишиной: всю зиму живёт без света за запертой дверью, а весной сдаёт комнаты студентам и прячет открытку за фото.","primary_genre":"Панк","primary_mood":"Протест","primary_theme":"Выбор","story_shelf":"Трагические истории","conflict_key":"повестка-на-выселение-против-запертой-двери","image_key":"открытка-за-фотографией-отца","turn_key":"комната-пережила-зиму","hook_key":"из-комнаты-не-выйду","sort_order":"1409","original_key":"boris-sluckij|nemka","author_name":"Борис Слуцкий","original_title":"Немка","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/boris-sluckij-nemka/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1986.","music_adaptations":[],"source_synopsis":"Осенью сорок первого русская немка из Москвы получает открытку-повестку: взять вещи и явиться на вокзал к отправке. Она отвечает единственным способом — «не пойду»: не открывает дверь, не зажигает свет, не топит печь, и соседи считают её умершей. Перебравшись так через зиму, она весной живая-здоровая торгует на толчке и сдаёт углы в своей комнате, а повестку хранит за портретом: в ней нет ни погони, ни конвоя — только перечень вещей, которые велено взять.","main_image":"открытка-повестка, спрятанная за портретом"},{"title":"Двор вдов","full_story":"В старом квартале по вечерам гаснут окна одновременно: здесь остались почти одни вдовы, привыкшие к подъёму с рассветом и сну вполглаза. Ночью они не выключают радио и слушают, как внизу звенит последний трамвай, — с этим звоном на минуту возвращаются молодость, танцы в клубе и голоса мужей. Утром они снова на скамейках, делятся семенами и новостями о внуках, а смерть зовут по имени-отчеству, как соседку.","hero_pov":"Вдова, слушающая последний трамвай","central_conflict":"День требует смирения и аккуратности, а ночь возвращает всю не прожитую до конца любовь.","emotional_arc":"От дисциплины дня к ночному возвращению жизни и утреннему спокойствию","ending_direction":"Поворот: трамвайный звон на минуту возвращает мужей — и женщины снова готовы жить день","hook_direction":"Трамвай помнит нас","genres":["Блюз","Эмбиент"],"moods":["Нежность","Светлая грусть"],"energy":"Низкая","themes":["Ночь","память"],"generator_brief":"Ноктюрн-блюз с трамвайными звонами и старым пианино; темп медленный, голос тёплый, ближе к шёпоту.","generator_story":"В квартале остались одни вдовы: днём они смиренны, а ночью слушают последний трамвай, и его звон на минуту возвращает им мужей, танцы и молодость — до нового рассвета.","primary_genre":"Блюз","primary_mood":"Нежность","primary_theme":"Ночь","story_shelf":"Трагические истории","conflict_key":"дневная-дисциплина-против-ночной-памяти","image_key":"звон-трамвая-над-кварталом-вдов","turn_key":"звон-возвращает-мужей-на-минуту","hook_key":"трамвай-помнит-нас","sort_order":"1410","original_key":"boris-sluckij|staruxi-bez-starikov","author_name":"Борис Слуцкий","original_title":"Старухи без стариков","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/boris-sluckij-staruxi-bez-starikov/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1986.","music_adaptations":[],"source_synopsis":"Целое поколение женщин осталось без мужей: война и трудовое столетие ломали мужчин первыми, и в городах вырастали квартиры и кварталы одних старушек. Они живут по-солдатски дисциплинированно, ложатся с солнцем, спят плохо и говорят о смерти запросто, как о соседках. Всё прожитое — любовь, долг, горе — возвращается к ним ночью, в звонах последнего трамвая.","main_image":"ночной трамвай, звенящий над кварталом вдов"},{"title":"Клавиши-могилы звуков","full_story":"Пианист Аркадий, не игравший ни ноты после того, как сгорела его музыкальная школа, находит на барахолке тот самый обгоревший инструмент. Ночью он трогает клавиши — и звуки, спавшие по одному под каждой, строятся в оркестр его несостоявшейся премьеры. К рассвету музыка распадается, но Аркадий впервые за девять лет доигрывает до конца и оставляет рояль у себя: пока играет — звучит.","hero_pov":"Пианист, девять лет не касавшийся клавиш","central_conflict":"Вина выжившего велит не играть, а молчащие клавиши требуют последнего концерта.","emotional_arc":"От немоты и вины к воскресшему оркестру и завершению","ending_direction":"Поворот: музыка распадается, но он доигрывает — и остаётся с инструментом жить","hook_direction":"Дозвучу за всех","genres":["Техно","Классика"],"moods":["Вина","Боль"],"energy":"Средняя","themes":["Поиск себя","музыка"],"generator_brief":"Тёмное техно с оркестровыми вспышками и глухим пульсом; куплеты — пыль и пепел, припев — звук восстает из-под клавиш.","generator_story":"Пианист, девять лет не игравший после пожара своей школы, находит обгоревший рояль; звуки под клавишами встают в оркестр, музыка распадается к рассвету, но он впервые доигрывает до конца.","primary_genre":"Техно","primary_mood":"Вина","primary_theme":"Поиск себя","story_shelf":"Трагические истории","conflict_key":"вина-немоты-против-последнего-концерта","image_key":"оркестр-из-спящих-под-клавишами-звуков","turn_key":"доигрывает-до-конца-впервые-за-девять-лет","hook_key":"дозвучу-за-всех","sort_order":"1411","original_key":"yurij-levitanskij|son-o-royale","author_name":"Юрий Левитанский","original_title":"Сон о рояле","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/yurij-levitanskij-son-o-royale/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1996.","music_adaptations":[],"source_synopsis":"Герою снится старый обгоревший рояль: под каждой клавишей — могила одного звука, все они были солдатами погибшей праздничной симфонии. Безумный музыкант снова касается клавиш — и мёртвые звуки оживают, строятся, играют войну и возмездие, пока музыка не фальшивит и не распадается. Герой просыпается в ужасе: музыкант опять идёт к роялю, и всё начнётся заново.","main_image":"оркестр, встающий из-под обгоревших клавиш"},{"title":"Архитектор несбыточных городов","full_story":"Архитектор Пётр Иванович после провала конкурса целыми днями чертит на даче невозможные города — с мостами через пролив и оперой на скале, — а жена собирает гостей и шутя водит экскурсии по «папиным руинам». Каждый, кто приходит в дом, получает у него в дар одну башню и комнату с видом на вечность. На пенсии он выигрывает-таки конкурс — но оставляет чертежи небу: людям нужнее было жить рядом со строящимся.","hero_pov":"Архитектор, возводящий города из воздуха","central_conflict":"Семья и коллеги требуют «взрослых» проектов, а его воздушные города кого-то грели всю жизнь.","emotional_arc":"От насмешек к признанию бесполезной пользы","ending_direction":"Поворот: он выигрывает настоящий конкурс — и всё равно продолжает строить для всех из воздуха","hook_direction":"Заходи, я всё построил","genres":["Синтвейв","Инди-поп"],"moods":["Вдохновение","Мечтательность"],"energy":"Средняя","themes":["Свобода","Мечта"],"generator_brief":"Воздушный синтвейв с колокольчиками и лёгкой бас-гитарой; куплеты — чертёж на траве, припев — город из облаков открыт всем.","generator_story":"Проваливший конкурс архитектор строит на даче невозможные города, и семья зовёт их папиными руинами; он дарит каждому по башне — и люди живут рядом с его стройкой теплее.","primary_genre":"Синтвейв","primary_mood":"Вдохновение","primary_theme":"Свобода","story_shelf":"Юмор: семейные драмы","conflict_key":"взрослые-проекты-против-воздушных-городов","image_key":"башня-из-облаков-над-дачей","turn_key":"выигрыш-конкурса-не-отменяет-неба","hook_key":"заходи-я-всё-построил","sort_order":"1412","original_key":"yurij-levitanskij|chelovek-stroyashhij-vozdushnye-zamki","author_name":"Юрий Левитанский","original_title":"Человек, строящий воздушные замки","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/yurij-levitanskij-chelovek-stroyashhij-vozdushnye-zamki/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1996.","music_adaptations":[],"source_synopsis":"Мечтатель лежит на траве, глядя в небо, и возводит воображаемые галереи, арки и целые города — и даже во сне продолжает достраивать. Всех прохожих он зовёт заходить, брать и жить. Жить в этих постройках нельзя, признаёт поэт, но без них жизнь была бы беднее и неуютнее: воздушные замки строятся из бескорыстья и простодушия.","main_image":"стройплощадка башен из облаков"},{"title":"Дорога одной ёлки","full_story":"Видеограф Марина получает заказ «показать зиму» и снимает путь одной ёлки: базар, где её покупает отец семейства с двумя детьми, балкон, свет гирлянд и детский восторг в полночь. Наутро её оператор приносит последний кадр — ёлку в метели пустого двора — и хочет вырезать, но Марина оставляет его финалом: именно он честнее календаря говорит, что год закрыт. Заказчик спорит, смотрит до конца и молча соглашается.","hero_pov":"Видеограф, монтирующая сюжет о зиме","central_conflict":"Заказ ждёт праздничной картинки, а правда зимы живёт в кадре со снежной мусоркой.","emotional_arc":"От новогодней суеты к честному финалу и лёгкости нового года","ending_direction":"Поворот: «некрасивый» кадр оставлен финалом — и именно он отпускает год","hook_direction":"Покажи зиму без мишуры","genres":["Синтвейв","Лоу-фай"],"moods":["Освобождение","Ирония"],"energy":"Низкая","themes":["Дорога","Праздник"],"generator_brief":"Лоу-фай синтвейв с шуршанием снега и детскими колокольчиками; куплеты — путь ёлки, припев — метель отпускает год.","generator_story":"Видеограф снимает заказ «показать зиму»: путь ёлки от базара до полуночи в гирляндах; последний кадр — ёлка в метели пустого двора — становится финалом, который честнее календаря закрывает год.","primary_genre":"Синтвейв","primary_mood":"Освобождение","primary_theme":"Дорога","story_shelf":"Юмор: семейные драмы","conflict_key":"праздничный-заказ-против-правды-двора","image_key":"ёлка-в-метели-пустого-двора","turn_key":"выброшенный-кадр-закрывает-год","hook_key":"покажи-зиму-без-мишуры","sort_order":"1413","original_key":"yurij-levitanskij|kak-pokazat-zimu","author_name":"Юрий Левитанский","original_title":"Как показать зиму","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/yurij-levitanskij-kak-pokazat-zimu/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1996.","music_adaptations":[],"source_synopsis":"Зима показана как кинолента через судьбу одной ёлки: её покупают на рынке и несут домой, она стоит на балконе в ожидании праздника, потом сияет вечером в мишуре — и наконец лежит выброшенная в метельном безлюдном дворе. Именно эта брошенная ёлка точнее календаря говорит, что год миновал и начался новый. Сквозь новогоднюю кутерьму пролетает время: дни длиннее, но холоднее.","main_image":"ёлка в метели пустого двора"},{"title":"Назад к вертикальной стене","full_story":"Экс-чемпион мотошоу Рустам после травмы стал успешным спортивным колумнистом, выступает на панелях, но чувствует, что «обезголосел». На пике карьеры он объявляет в прямом эфире об уходе и возвращается в маленький передвижной цирк — гонять по вертикальной стене бочки вниз головой, как отец. Коллеги называют это капризом, а он в первом же заезде слышит, как стена возвращает ему дыхание.","hero_pov":"Колумнист, вернувшийся в мотошоу","central_conflict":"Известность и стабильность против вертикальной стены, на которой только и дышится.","emotional_arc":"От успешной пустоты к риску и возвращению голоса","ending_direction":"Поворот: в первом же заезде вниз головой стена возвращает ему всё","hook_direction":"Вернусь к своей стене","genres":["Панк","Рок"],"moods":["Освобождение","Драйв"],"energy":"Взрывная","themes":["Выбор","сцена"],"generator_brief":"Бешеный панк-рок с рёвом мотора и стеной гитар; куплеты — студия и скука, припев — разгон по вертикали.","generator_story":"Успешный спортивный колумнист, бывший чемпион мотошоу, объявляет в эфире об уходе и возвращается в маленький цирк гонять по вертикальной стене — и в первом заезде снова обретает голос.","primary_genre":"Панк","primary_mood":"Освобождение","primary_theme":"Выбор","story_shelf":"Трагические истории","conflict_key":"успешность-против-зова-стены","image_key":"мотоцикл-на-вертикальной-стене-бочки","turn_key":"первый-заезд-возвращает-дыхание","hook_key":"вернусь-к-своей-стене","sort_order":"1414","original_key":"aleksandr-mezhirov|ballada-o-cirke","author_name":"Александр Межиров","original_title":"Баллада о цирке","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/aleksandr-mezhirov-ballada-o-cirke/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2009.","music_adaptations":[],"source_synopsis":"Сын цирковой акробатки, родившийся в шарабане на гастролях, вырос в цирке и гонял мотоцикл по вертикальной стене, пока война не сделала его поэтом. После войны литература разочаровала его: он «обезголосел» и публично объявил, что возвращается к стене и мотоциклу, — литературный свет почуял позёрство. Зимними гастролями он снова гоняет вниз головой по стене огромной бочки, и вертикальная стена возвращает ему всё.","main_image":"мотоцикл на вертикальной стене бочки"},{"title":"Сыграю под своим именем","full_story":"Киберспортсмен Егор с детства играет под ником в честь умершего кумира — так его зовут комментаторы, спонсоры и миллион подписчиков, а дед в деревне упорно пишет ему «Егорушка». Перед главным финалом сезона он просит организаторов вывести на табло настоящее имя — впервые за десять лет. Под своим именем он играет свободнее, чем под чужим, и даже проигрыш берёт как свой.","hero_pov":"Киберспортсмен, уставший от чужого ника","central_conflict":"Ник собрал славу и аудиторию, а крестильное имя — единственное, под которым он свой.","emotional_arc":"От двоимости к цельности и спокойной силе","ending_direction":"Поворот: под настоящим именем он играет свободнее — и результат уже не главное","hook_direction":"Моё имя — не ник","genres":["Хип-хоп","Электропоп"],"moods":["Уверенность","Смелость"],"energy":"Высокая","themes":["Поиск себя","голос"],"generator_brief":"Уверенный хип-хоп с медным басом и клэпами; куплеты — сцена под ником, припев — имя на табло во весь экран.","generator_story":"Киберспортсмен десять лет играет под ником в честь кумира, а дед зовёт его Егором; перед главным финалом он выводит на табло настоящее имя и впервые играет свободнее, чем под чужим.","primary_genre":"Хип-хоп","primary_mood":"Уверенность","primary_theme":"Поиск себя","story_shelf":"Юмор: семейные драмы","conflict_key":"ник-против-крестильного-имени","image_key":"настоящее-имя-на-табло","turn_key":"выход-под-своим-именем","hook_key":"mojo-imya-ne-nik","sort_order":"1415","original_key":"aleksandr-mezhirov|ballada-o-vozvrashhennom-imeni","author_name":"Александр Межиров","original_title":"Баллада о возвращенном имени","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/aleksandr-mezhirov-ballada-o-vozvrashhennom-imeni/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2009.","music_adaptations":[],"source_synopsis":"Деревенский парень попадает в московскую пивную и становится великим игроком в бильярд — поэты уподобляют такого игрока мудрецу и пророку. Товарищи переименовали его из Егора в Сергея — в честь любимого поэта. Со временем первородное имя вернулось к нему вместе с даром: он сменил кий на перо, потому что главное — остаться собой, и всё входит в земную гармонию.","main_image":"дед, зовущий внука по-крестильному"},{"title":"Пост у грядки гладиолусов","full_story":"Семья уезжает на выходные, и старый пёс Гай остаётся единственным сторожем грядки гладиолусов, выращенных бабушкой к районной выставке. Ночью налетает гроза, ветер ломает цветоносы, и Гай всю ночь воет на гром, не сойдя с поста ни на шаг. Хозяева возвращаются к полегшей грядке и лежащему возле неё псу — с ошейником-пропуском на выставку, которая теперь не случится.","hero_pov":"Пёс, не сошедший с поста","central_conflict":"Верность приказу «сторожи» против стихии, которой всё равно, что ты ждал счастья.","emotional_arc":"От радостного ожидания через бурю к верности до конца","ending_direction":"Поворот: грядка погибла, но пост не оставлен — и хозяева хоронят сторожа с почестями","hook_direction":"Я держал этот пост","genres":["Панк","Рок"],"moods":["Вина","Боль"],"energy":"Взрывная","themes":["выбор","животные"],"generator_brief":"Рваный панк с воем ветра и тяжёлым финальным аккордом; куплеты — тёплый пост, припев — гром ломает всё.","generator_story":"Пёс остаётся сторожить дачную грядку гладиолусов, выращенных к выставке; ночная гроза ломает цветы, но он не сходит с поста до возвращения хозяев — и они хоронят сторожа с почестями.","primary_genre":"Панк","primary_mood":"Вина","primary_theme":"выбор","story_shelf":"Люди и животные","conflict_key":"гроза-против-верности-посту","image_key":"пёс-у-поломанной-грядки","turn_key":"пост-не-оставлен-до-возвращения","hook_key":"ya-derzhal-etot-post","sort_order":"1416","original_key":"vadim-shefner|sobaka-storozhila-gladiolusy","author_name":"Вадим Шефнер","original_title":"Собака сторожила гладиолусы","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/vadim-shefner-sobaka-storozhila-gladiolusy/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2002.","music_adaptations":[],"source_synopsis":"Короткая гротескная зарисовка: собака честно сторожит дачные гладиолусы и ждёт счастья, ветер её подбадривает. Вдруг гремит гром, цветы мнутся и теряют выставочный вид — и пёс с воем умирает от несбывшегося. Репортёрская точность и наивная надежда сторожа дают трагикомический удар в финале.","main_image":"пёс на посту у поломанной грозой грядки"},{"title":"Дедушкин рекорд","full_story":"На семейной спартакиаде в честь юбилея дома внук-старшеклассник впервые пробегает стометровку быстрее, чем дед когда-то на областном финале. Дед не грустит: достаёт из коробки свою потемневшую медаль и вешает внуку на шею — пусть висит, пока не обгонит кто-нибудь из правнуков. За столом дед поднимает тост: рекорды — как листва, они каждый раз вырастают новые, а дерево — семья — одно.","hero_pov":"Дед, уступивший собственный рекорд","central_conflict":"Гордыне хочется сохранить первенство, а радость — увидеть, как тебя превзошли свои же.","emotional_arc":"От щекотного укола самолюбия к гордости и передаче эстафеты","ending_direction":"Поворот: медаль вручена внуку — слава обновилась, и это по-семейному справедливо","hook_direction":"Обгоняй, я аплодирую","genres":["Регги","Поп"],"moods":["Ирония","Тепло"],"energy":"Средняя","themes":["выбор","Детство"],"generator_brief":"Ленивое солнечное регги с хлопками и духовыми; куплеты — забег на траве, припев — тост за обновляющуюся славу.","generator_story":"На семейной спартакиаде внук впервые пробегает стометровку быстрее дедовского рекорда; дед вручает ему свою старую медаль и поднимает тост: рекорды обновляются, как листва, а дерево-семья одно.","primary_genre":"Регги","primary_mood":"Ирония","primary_theme":"выбор","story_shelf":"Юмор: семейные драмы","conflict_key":"гордыня-против-радости-за-внука","image_key":"потемневшая-медаль-на-шее-внука","turn_key":"медаль-передана-по-наследству","hook_key":"obgonyaj-ya-aplodiruyu","sort_order":"1417","original_key":"vadim-shefner|rekordy","author_name":"Вадим Шефнер","original_title":"Рекорды","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/vadim-shefner-rekordy/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2002.","music_adaptations":[],"source_synopsis":"Забытый бегун Лядумега, чьи рекорды давно побиты, помнится теперь только по нотации: а как он всё-таки бегал! По тем же дорожкам теперь мчатся молодые, лёгкие, как ветер, и собирают золото. Поэт считает это справедливым: слава обновляется, как листва, и гнаться за ней незачем — она не лежит в ящике, а каждый раз вырастает заново.","main_image":"медаль деда на шее внука"},{"title":"Просёлок на двух колёсах","full_story":"Отец и сын-подросток, полгода не разговаривавшие после скандала из-за отъезда матери, едут на великах через знойный просёлок к далёкой реке. Спуски, подъёмы, шмели, пыль — и где-то на третьем километре ссора тает сама, потому что её некуда везти в гору. У реки они молча делят последний сухарь, и отцу вдруг не видно конца этому счастью — и не надо.","hero_pov":"Отец, крутящий педали рядом с молчащим сыном","central_conflict":"Полгода обиды против двадцати километров дороги, на которой обида не выдерживает подъёма.","emotional_arc":"От ледяного молчания к общему поту и тихому примирению","ending_direction":"Поворот: у реки ссоры больше нет — и конца этому счастью не видно","hook_direction":"Крути, пока не стемнеет","genres":["Регги","Поп-рок"],"moods":["Эйфория","Радость"],"energy":"Высокая","themes":["дорога","семья"],"generator_brief":"Солнечное регги-рок с перкусией шмелей и хором педалей; куплеты — подъём в гору, припев — ветер с реки.","generator_story":"Отец и сын, полгода не разговаривавшие после семейного скандала, едут на великах через знойный просёлок; на подъёмах обида тает, и у реки делить остаётся только сухарь и счастье.","primary_genre":"Регги","primary_mood":"Эйфория","primary_theme":"дорога","story_shelf":"Юмор: семейные драмы","conflict_key":"полгода-обиды-против-подъёма","image_key":"два-колеса-в-пыли-просёлка","turn_key":"ссора-тает-на-третьем-километре","hook_key":"kruti-poka-ne-stemnelo","sort_order":"1418","original_key":"aleksandr-kushner|velosipednye-progulki","author_name":"Александр Кушнер","original_title":"Велосипедные прогулки","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/aleksandr-kushner-velosipednye-progulki/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2025.","music_adaptations":[],"source_synopsis":"Летняя велопоездка за город: знойный полдень, просёлок, шмели, мелькание колёс, лесная тень — особое удовольствие трудной, пыльной дороги со спусками и подъёмами. Рядом, правда, пусто: даль — и не с кем поделиться. Финал — вопрос без ответа: если это и есть счастье, то где его конец, не видно.","main_image":"два колеса в пыли знойного просёлка"},{"title":"Две секунды в одном кадре","full_story":"Семейный вечер идёт по кругу вокруг одного снимка: дед пойман камерой в прыжке между прошлым и настоящим, и на фото у него «два носа» и подозрительно три руки. Внуки ржут и требуют переснять, а дед твёрдо стоит на своём: так и было — в тот год он уходил с завода в музыканты и буквально жил в двух местах сразу. Семья соглашается: брак снимка становится его лучшим портретом, и его вешают в центр стены.","hero_pov":"Дед с «тремя руками» на снимке","central_conflict":"Домашние видят брак, а для героя этот смазанный кадр — единственная правда о его двух жизнях.","emotional_arc":" от насмешки к признанию и семейному миру","ending_direction":"Поворот: «испорченный» снимок вешают в центр стены как главный портрет","hook_direction":"Так и было, честно","genres":["Хип-хоп","Поп"],"moods":["Ирония","Тепло"],"energy":"Средняя","themes":["прощение","семья"],"generator_brief":"Игривый поп-хип-хоп с сэмплами затвора и семейным смехом; куплеты — спор за столом, припев — «так и было».","generator_story":"Семья смеётся над смазанным фото деда с двумя носами и тремя руками, а он настаивает: так и было — в тот год он жил двумя жизнями сразу, и этот брак снимка становится его лучшим портретом.","primary_genre":"Хип-хоп","primary_mood":"Ирония","primary_theme":"прощение","story_shelf":"Юмор: семейные драмы","conflict_key":"брак-снимка-против-правды-о-двух-жизнях","image_key":"три-руки-на-одном-снимке","turn_key":"брак-вешают-в-центр-стены","hook_key":"tak-i-bylo-chestno","sort_order":"1419","original_key":"aleksandr-kushner|fotografiya","author_name":"Александр Кушнер","original_title":"Фотография","original_language":"Russian","origin_country":"Россия","original_year":"1966","source_url":"https://rustih.com/aleksandr-kushner-fotografiya/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2025.","music_adaptations":[],"source_synopsis":"Ироническое стихотворение о смазанном снимке: случайный фотограф поймал героя на набережной в движении, и на фото у того как будто два носа, размытая щека и даже три руки. Мгновение растянулось на два мига — человек размазан во времени между двумя точками пути. Домашние подтрунивают, а герой отвечает, что так и было: он и правда был в двух местах сразу.","main_image":"три руки на одном снимке"},{"title":"Кто кого сторожит","full_story":"Охранник ночного коворкинга Тимофей замечает в окне дома напротив художника, работающего при одной лампе до рассвета, и целую смену следит за ним вместо мониторов. Под утро выясняется, что художник всю ночь писал сам ночной двор — с одинокой фигурой охранника у входа. Тимофей не пишет рапорт о нарушении режима: он впервые за годы записывает в блокноте свою строчку — о том, каково быть увиденным.","hero_pov":"Ночной охранник, ставший натурой","central_conflict":"Служба требует считать незагасшее окно нарушением, а оно оказалось единственным, кто видел его самого.","emotional_arc":"От служебной скуки к тайне взаимного наблюдения и первому своему слову","ending_direction":"Поворот: вместо рапорта — первая строчка; сторож сам стал картиной","hook_direction":"Мы ночная смена","genres":["Техно","Эмбиент"],"moods":["Вдохновение","Тревога"],"energy":"Средняя","themes":["Ночь","город"],"generator_brief":"Минимальное техно с нойзом города и редкими нотами фортепиано; куплеты — обход, припев — два окна горят друг на друга.","generator_story":"Охранник ночного коворкинга всю смену наблюдает за художником в окне напротив, а под утро узнаёт, что тот писал его самого; вместо рапорта он записывает свою первую строчку.","primary_genre":"Техно","primary_mood":"Вдохновение","primary_theme":"Ночь","story_shelf":"Трагические истории","conflict_key":"рапорт-против-увиденности","image_key":"два-светящихся-окна-через-двор","turn_key":"рапорт-заменён-первой-строкой","hook_key":"my-nochnaya-smena","sort_order":"1420","original_key":"aleksandr-kushner|nochnoj-dozor","author_name":"Александр Кушнер","original_title":"Ночной дозор","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/aleksandr-kushner-nochnoj-dozor/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2025.","music_adaptations":[],"source_synopsis":"Городской ночной дозор на рассвете патрулирует тихие улицы мимо вывески сапожника и каланчи и замечает окна, где кто-то не гасит свет. Капитан спрашивает: не спит знахарь или картёжник? Солдат отвечает: это художник, чуднее которого нет — не угадать, что он выберет для картины. И до утра неясно, кто здесь настоящий страж — дозорные или художник, наблюдающий за ними.","main_image":"два светящихся окна друг напротив друга"},{"title":"Гость, которого выжали","full_story":"Уличная поэтесса Вера приводит на закрытый приём галереи живого бездомного поэта-заику, которого прозвала своим дождём: он приносит прохладу всем, к кому приходит. Сначала гости умиляются «экзотическому гостю», потом начинают выжимать из него комплименты, тосты и стихи до последней капли. Вера забирает его посреди вечера, а наутро целует влажное пятно на асфальте у служебного входа — единственное, что осталось от дождя в этом доме.","hero_pov":"Поэтесса, приведшая дождя в гости","central_conflict":"Светский дом хочет приручить и выжать вольную стихию, а она имеет право просто идти рядом.","emotional_arc":"От надежды на приятие через ярость к уходу вдвоём","ending_direction":"Поворот: они уходят вместе, и пятнышко воды на асфальте важнее всей галереи","hook_direction":"Дождь, не отдам вас им","genres":["Драм-н-бейс","Альтернативный рок"],"moods":["Злость","Боль"],"energy":"Взрывная","themes":["Свобода","голос"],"generator_brief":"Бурный драм-н-бейс с ливнем перкуссии и струнными охоты; куплеты — приём в галерее, припев — уход под грозу.","generator_story":"Поэтесса приводит на светский приём бездомного поэта, как живой дождь; гости выжимают его насмешками до капли, и она уводит его прочь — наутро целуя пятно воды на асфальте.","primary_genre":"Драм-н-бейс","primary_mood":"Злость","primary_theme":"Свобода","story_shelf":"Трагические истории","conflict_key":"светская-охота-против-вольного-дождя","image_key":"пятно-дождя-на-асфальте-галереи","turn_key":"уход-вдвоём-из-гостиной","hook_key":"dozhd-ne-otdam-vas-im","sort_order":"1421","original_key":"bella-axmadulina|skazka-o-dozhde","author_name":"Белла Ахмадулина","original_title":"Сказка о дожде","original_language":"Russian","origin_country":"Россия","original_year":"1962","source_url":"https://rustih.com/bella-axmadulina-skazka-o-dozhde/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2010.","music_adaptations":[],"source_synopsis":"Поэма-сказка о героине-поэтессе, которую повсюду сопровождает живой дождь — преданный, как дитя или зверёк, символ чистоты и вольной стихии. Изгнанница среди благополучного света сначала тяготится им, потом жалеет и приводит в гости в образцовый дом. Гости устраивают на дождь настоящую охоту: его ловят, выжимают, топчут; героиня уходит, целуя на сухом асфальте последнее пятнышко воды, и городу остаётся засуха.","main_image":"пятно дождя на сухом асфальте"},{"title":"Футляр с портретом","full_story":"Скрипачка забегает в антикварную лавку переждать ливень и слышит, как вещи на полках молча выпрашивают, чтобы их спели. Она требует с витрины потёртый футляр для нот, и владелец-старик, отговаривавший её сервизами, вдруг рассказывает про свою любовь столетней давности и девушку, чей портрет лежит внутри. Скрипачка уносит футляр, оставив портрет старику, — а дома за ужином говорит родным, что, возможно, всё это выдумка, но теперь их дом причастен к той истории, и футляр поёт у неё в руках.","hero_pov":"Скрипачка, услышавшая плач вещей","central_conflict":"Лавка торгует стариной по весу, а вещи хотят, чтобы их историю наконец спели и взяли в жизнь.","emotional_arc":"От случайного захода к выбору вещи по голосу и причастности к чужой любви","ending_direction":"Поворот: портрет остаётся старику, а пустой футляр — ей, и оба получают своё","hook_direction":"Спой, моя вещь","genres":["Блюз","Джаз"],"moods":["Нежность","Тоска"],"energy":"Средняя","themes":["Свобода","прошлое"],"generator_brief":"Камерный блюз с щипком контрабаса и пыльным фортепиано; куплеты — лавка, припев — вещь поёт свою историю.","generator_story":"Скрипачка, случайно зайдя в антикварную лавку, слышит плач вещей и выбирает старый футляр; владелец отдаёт его, оставив себе портрет погибшей любви, и футляр начинает петь в её руках.","primary_genre":"Блюз","primary_mood":"Нежность","primary_theme":"Свобода","story_shelf":"Любовные сцены","conflict_key":"вес-старины-против-голоса-вещи","image_key":"футляр-без-портрета-в-руках","turn_key":"портрет-остаётся-старику","hook_key":"spoj-moya-veshh","sort_order":"1422","original_key":"bella-axmadulina|priklyuchenie-v-antikvarnom-magazine","author_name":"Белла Ахмадулина","original_title":"Приключение в антикварном магазине","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/bella-axmadulina-priklyuchenie-v-antikvarnom-magazine/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2010.","music_adaptations":[],"source_synopsis":"Героиня случайно заходит в антикварный магазин, где угрюмый двухсотлетний старик-владелец поначалу её прогоняет. Она слышит беззвучный плач вещей, требующих быть воспетыми, и просит именно старый футляр. Старик рассказывает историю своей любви столетней давности — красавицы, за которой сватался и знатный чужак, — и отдаёт футляр, оставив себе портрет из него. Дома героиня признаёт рассказ выдумкой — но теперь в её доме живут портрет, звон стекла и причастность к большой истории.","main_image":"футляр, из которого вынули портрет"},{"title":"Мы не выучили ноты","full_story":"Две подруги детства честно отзанимались восемь лет в музыкалке — и так и не поладили с роялём: он молчал, они шалили. Одна стала звездой разговорного жанра, другая — тишайшей поэтессой, и на юбилее первой они вспоминают свои молчаливые уроки. Поэтесса хочет крикнуть со сцены, что они с подругой — одно и то же недоразумение с нотами, обернувшееся речью; вместо крика обнимает её, и зал аплодирует молчанию.","hero_pov":"Поэтесса, не поладившая с роялём","central_conflict":"Рояль требовал подчинения нотам, а у обеих девочек звук пошёл через слово — и их пришлось разлучить с музыкой.","emotional_arc":"От детской вины перед инструментом к гордости за свой путь","ending_direction":"Поворот: вместо крика о сходстве — объятие, и зал слышит их молчание","hook_direction":"Мой звук без нот","genres":["Хип-хоп","Соул"],"moods":["Вдохновение","Нежность"],"energy":"Средняя","themes":["Поиск себя","музыка"],"generator_brief":"Тёплый соул-хип-хоп с клавишами музыкалки и живым басом; куплеты — уроки и шалости, припев — свой звук без нот.","generator_story":"Две подруги детства не поладили с роялём и не выучили ноты, зато обе нашли свой звук в слове; на юбилее одна хочет крикнуть о сходстве, но вместо крика обнимает подругу на сцене.","primary_genre":"Хип-хоп","primary_mood":"Вдохновение","primary_theme":"Поиск себя","story_shelf":"Любовные сцены","conflict_key":"ноты-против-своего-звука","image_key":"две-девочки-у-молчащего-рояля","turn_key":"крик-заменён-объятием","hook_key":"moj-zvuk-bez-not","sort_order":"1423","original_key":"bella-axmadulina|uroki-muzyki","author_name":"Белла Ахмадулина","original_title":"Уроки музыки","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/bella-axmadulina-uroki-muzyki/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2010.","music_adaptations":[],"source_synopsis":"Посвящение подруге-поэту: обе в детстве склонялись над клавишами, и обе рояль так и не понял — инструмент и девочка остались во взаимной глухонемоте. Музыку они «не выучили», но творчество стало для них другим кровотечением звука — словом. Героине хочется крикнуть о своём сходстве с великой собеседницей, но вместо крика приходят слёзы.","main_image":"две девочки, сбежавшие от рояля"},{"title":"Депо мамонтов","full_story":"Старый машинист Тихон каждое воскресенье приходит на запасной путь, где рядами стоят списанные локомотивы, — находит своего, трёт рукавом борт и рассказывает ему про шахтёрские составы, про людей, которых тот возил. Внук снимает эти визиты на телефон для канала про железную дорогу и поначалу стесняется деда. В финале над депо медленно ложится первый снег, и внук впервые не выключает камеру: ржавчина уходит под белый, и это красивее любого репорта.","hero_pov":"Старый машинист у списанного локомотива","central_conflict":"Внук стыдится сентиментального деда перед подписчиками — пока не видит, как снег примиряет железо.","emotional_arc":"От неловкости к тихой гордости и передаче памяти","ending_direction":"Поворот: внук не выключает камеру — снег над депо становится их общим фильмом","hook_direction":"Спи, железный мамонт","genres":["Техно","Рок"],"moods":["Освобождение","Светлая грусть"],"energy":"Средняя","themes":["Дорога","память"],"generator_brief":"Индустриальное техно-рок с гудками и скрежетом; куплеты — обход депо, припев — снег глушит ржавчину.","generator_story":"Старый машинист каждое воскресенье приходит к списанному локомотиву рассказывать про былые составы; внук стесняется снимать деда, пока первый снег над депо не примиряет железо и людей.","primary_genre":"Техно","primary_mood":"Освобождение","primary_theme":"Дорога","story_shelf":"Трагические истории","conflict_key":"списание-против-благодарности","image_key":"ржавые-спины-под-первым-снегом","turn_key":"снег-примиряет-железо","hook_key":"spi-zheleznyj-mamont","sort_order":"1424","original_key":"yaroslav-smelyakov|kladbishhe-parovozov","author_name":"Ярослав Смеляков","original_title":"Кладбище паровозов","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/yaroslav-smelyakov-kladbishhe-parovozov/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1972.","music_adaptations":[],"source_synopsis":"Заброшенное депо старых паровозов похоже на кладбище: ржавые корпуса, разбитые фонари, мёртвые рычаги — «мамонты пятилеток», труд слесарей и шахтёров былой эпохи. Мёртвым машинам уже ни к чему тепло и забота, люди и песни ушли из вагонов, а в железе и в человеке молча зреют ненависть и любовь. Финал умиротворён: железо должно учить всех, и медленно, спокойно падает первый снег.","main_image":"ржавые спины паровозов под первым снегом"},{"title":"Три поцелуя на прощание","full_story":"Студент-третьекурсник Антоха всё лето катал первую любовь на синей электричке до купола планетария: делили один наушник, выбирали обои для несуществующей квартиры в витринах. В августе она приезжает на свидание с новым парнем на мотоцикле и просит «остаться друзьями». Антоха трижды целует её в лоб — за всё лето, за обои и за электричку — и садится в обратный вагон один, уже без злости.","hero_pov":"Студент, прощающийся с первым летом любви","central_conflict":"Обида требует хлопнуть дверью, а благодарность за лето — попрощаться красиво и трижды.","emotional_arc":"От уязвлённости к взрослому прощанию без злости","ending_direction":"Поворот: три поцелуя вместо скандала — и обратный вагон один, но живой","hook_direction":"Счастливо, это всерьёз","genres":["Блюз","Фолк"],"moods":["Светлая грусть","Нежность"],"energy":"Средняя","themes":["прощение","расставание"],"generator_brief":"Городской фолк-блюз с гитарным перебором и гудком электрички; куплеты — лето в наушнике, припев — три поцелуя на перрон.","generator_story":"Студент всё лето катал первую любовь на электричке и выбирал с ней обои для будущей квартиры; в августе она приходит с другим, и он прощается тремя поцелуями в лоб — без злости.","primary_genre":"Блюз","primary_mood":"Светлая грусть","primary_theme":"прощение","story_shelf":"Любовные сцены","conflict_key":"обида-против-благодарности-за-лето","image_key":"один-наушник-в-синей-электричке","turn_key":"три-поцелуя-вместо-скандала","hook_key":"schastlivo-eto-vserjez","sort_order":"1425","original_key":"yaroslav-smelyakov|lyubka","author_name":"Ярослав Смеляков","original_title":"Любка","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/yaroslav-smelyakov-lyubka/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1972.","music_adaptations":[],"source_synopsis":"Посреди лета герой вспоминает юношескую любовь: синие вагоны пригородных поездов, свидания у заставы, кафе на бульваре, театры и совместный выбор обоев для будущей квартиры. Любка переменилась — загуляла с другим, и герой обижен: он готов уехать, поступить учиться и жениться на другой, хотя прежним уже не будет. Прощание повторено трижды — окончательно и наотрез.","main_image":"синяя электричка, уходящая без него"},{"title":"Галоп на бронзовой четвёрке","full_story":"Служащий театрального цеха Веня по ночам, развозя декорации на грузовой «Газели», воображает, что правит четвёркой бронзовых коней, снятых с фронтона: галопом догоняет девушку в плаще у светофора и зовёт в своё село — к колодцу и старому ясеню, где его знают без псевдонима. Днём он репетирует в подвале первую собственную песню и мечтает спеть её под оркестр — и даже спасти всех своих великих из учебника. Утром Веня ставит «Газель» у служебного входа и впервые заходит внутрь не с коробками, а с гитарой.","hero_pov":"Театральный грузчик с гитарой наперевес","central_conflict":"Днём он возит чужие декорации, а ночью его квадрига требует догнать свою жизнь.","emotional_arc":"От грузовой рутины к ночному галопу мечты и первому шагу внутрь","ending_direction":"Поворот: с гитарой — в служебную дверь: из перевозчика становится входящим","hook_direction":"Запрягай, я готов","genres":["EDM","Эпик-рок"],"moods":["Эйфория","Мечтательность"],"energy":"Высокая","themes":["Поиск себя","сцена"],"generator_brief":"Огромный EDM с эпик-хорами и цокотом копыт; куплеты — ночной развоз декораций, припев — галоп за своей жизнью.","generator_story":"Театральный грузчик ночами воображает, что правит бронзовой квадригой с фронтона, догоняет незнакомку и зовёт её в родное село; утром он впервые входит в служебную дверь не с коробками, а с гитарой.","primary_genre":"EDM","primary_mood":"Эйфория","primary_theme":"Поиск себя","story_shelf":"Любовные сцены","conflict_key":"рутина-перевозки-против-квадриги-мечты","image_key":"бронзовые-кони-над-ночным-городом","turn_key":"вход-в-служебную-дверь-с-гитарой","hook_key":"zapryagaj-ya-gotov","sort_order":"1426","original_key":"mihail-svetlov|artist","author_name":"Михаил Светлов","original_title":"Артист","original_language":"Russian","origin_country":"Россия","original_year":"1948","source_url":"https://slova.org.ru/svetlov/artist/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1964.","music_adaptations":[],"source_synopsis":"Герой — мечтатель-артист, который в воображении запрягает четвёрку коней с фронтона Большого театра и мчится, догоняя прекрасную незнакомку: зовёт её в деревню, к колодцу и ясеню, обещает показать себя настоящего, без псевдонима, на виду у земляков. Он мечтает запеть под оркестр, сыграть бессмертного солдата, спасти великих из прошлого — и уверен, что артист и художник обязаны вторгаться в грядущие дни.","main_image":"бронзовая квадрига, мчащаяся по городу"},{"title":"Семь копеек на трамвай","full_story":"Начинающий поэт получает в редакции первый гонорар мелочью и на остановке знакомится со старушкой, которая пересчитывает кучку монет: до дочки на другом конце города не хватает ровно на трамвай. Он сгребает ей всю свою мелочь — «на обратный тоже», — а вечером в писательском клубе, где как раз гремят марши, советует коллегам записать ему это в единственные недостатки. Старушка тем временем едет через весь город и впервые за год попадает на чай к дочери.","hero_pov":"Молодой поэт с гонораром мелочью","central_conflict":"Гонорар мал и нужен самому, а трамвай чужой старушки идёт прямо сейчас.","emotional_arc":"От неловкой встречи к тихой радости обоих","ending_direction":"Поворот: мелочь поэта довозит старушку до дочери — жалость оказывается лучшей строкой года","hook_direction":"Держи, на обратный","genres":["Регги","Фолк"],"moods":["Тепло","Ирония"],"energy":"Средняя","themes":["Дорога","поддержка"],"generator_brief":"Доброе регги с губной гармошкой и звоном трамвая; куплеты — остановка, припев — «на обратный возьми».","generator_story":"Молодой поэт получает первый гонорар мелочью и встречает на остановке старушку, которой не хватает на трамвай к дочери; он отдаёт ей всё и в клубе называет жалость своим единственным недостатком.","primary_genre":"Регги","primary_mood":"Тепло","primary_theme":"Дорога","story_shelf":"Юмор: семейные драмы","conflict_key":"первый-гонорар-против-чужой-нужды","image_key":"ладонь-с-мелочью-на-трамвай","turn_key":"жалость-названа-недостатком","hook_key":"derzhi-na-obratnyj","sort_order":"1427","original_key":"mihail-svetlov|starushka","author_name":"Михаил Светлов","original_title":"Старушка","original_language":"Russian","origin_country":"Россия","original_year":"1927","source_url":"https://slova.org.ru/svetlov/starushka/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1964.","music_adaptations":[],"source_synopsis":"Разговор героя с одинокой старушкой: времена переменились, человек теперь «не на месте», ей скучно и страшно, а на трамвай до окраины не хватает мелочи. Герой отдаёт ей свой скромный гонорар за стихи — на проезд и с запасом. Напоследок он обращается к коллеге-певцу маршевых од: пусть считает жалость к старушкам единственным недостатком автора.","main_image":"монеты на трамвай в ладони старушки"},{"title":"Газета и тарелка супа","full_story":"Подросток Дима безошибочно узнаёт по глазам вечера, когда отец опять «задержался после смены»: тот прячется за газетой, дышит чуть вбок, а мама уже набирает воздух для упрёка. Дима сердцем на стороне отца — того самого весёлого, который учил его папке управлять, — и злит мать этим. Прошло двадцать лет: за праздничным столом Дима поднимает первую рюмку — и ловит в зеркале мамин взгляд, тот самый, из детства; он ставит рюмку и наливает себе компот.","hero_pov":"Сын, всегда читавший глаза отца","central_conflict":"Любовь к отцу против материнской правоты: мальчик выбирает сторону сердца и всю жизнь расплачивается.","emotional_arc":"От детской половинчатости к взрослому выбору без всяких половин","ending_direction":"Поворот: увидев мамин взгляд на своей рюмке, он ставит её и наливает компот","hook_direction":"Я тебя всё равно вижу","genres":["Блюз","Фолк"],"moods":["Вина","Грусть"],"energy":"Низкая","themes":["прощение","семья"],"generator_brief":"Домашний блюз с гитарным боями и тарелками на кухне; куплеты — вечер и газета, припев — молчаливое «вижу тебя».","generator_story":"Подросток всегда безошибочно узнаёт вечера, когда отец прячет хмель за газетой, и в ссорах сердцем на его стороне; годы спустя он сам поднимает рюмку — и, поймав мамин взгляд, ставит её.","primary_genre":"Блюз","primary_mood":"Вина","primary_theme":"прощение","story_shelf":"Трагические истории","conflict_key":"материнская-правота-против-любви-к-отцу","image_key":"газета-как-щит-отца","turn_key":"рюмка-заменена-компотом","hook_key":"ya-tebya-vse-ravno-vizhu","sort_order":"1428","original_key":"konstantin-vanshenkin|otec-moj-pil-skryvaya-eto","author_name":"Константин Ваншенкин","original_title":"Отец мой пил, скрывая это...","original_language":"Russian","origin_country":"Россия","original_year":"1953","source_url":"https://slova.org.ru/vanshenkin/otec-moj-pil-skryvaya-eto/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2012.","music_adaptations":[],"source_synopsis":"Отец мальчика выпивал, но старательно скрывал это: брал газету, закуривал, выглядывал трезвым и лишь «дышал немного вбок» — сын безошибочно читал его по глазам. Когда начинались материнские упрёки, сын сердцем был на стороне отца — весёлого и близкого, — прощая его и осуждая одновременно. Годы спустя отца нет, и мать с тревогой смотрит уже на праздничную рюмку самого сына.","main_image":"газета как щит отца за столом"},{"title":"Позвони, как доберёшься","full_story":"Ночной таксист Рустам везёт последний заказ по пустой трассе: луна лежит на дне кюветов, спящие деревни притворяются мёртвыми, филин ухает единственным живым. Между заказами он по одному набирает старых друзей — не разговаривать, а просто услышать голос и повесить трубку. Под утро на посадочной берёт免费 попутчика — одноклассника, которого не видел двадцать лет, и они молчат вместе до самого города.","hero_pov":"Ночной таксист, обзванивающий друзей","central_conflict":"Трасса растянула всех друзей по стране, и голос в трубке — единственный способ увидеться.","emotional_arc":"От щемящего одиночества ночной дороги к молчаливой встрече","ending_direction":"Поворот: попутчик-одноклассник едет бесплатно — они «увиделись» впервые за двадцать лет","hook_direction":"Голос важнее маршрута","genres":["Синтвейв","Эмбиент"],"moods":["Нежность","Спокойствие"],"energy":"Средняя","themes":["Дорога","дружба"],"generator_brief":"Ночной синтвейв с шумом шин и далёким саксофоном; куплеты — километры, припев — гудки друзей в динамике.","generator_story":"Ночной таксист на пустой трассе между заказами обзванивает старых друзей, чтобы только услышать голос; под утро он бесплатно подбирает попутчика — одноклассника, не виденного двадцать лет.","primary_genre":"Синтвейв","primary_mood":"Нежность","primary_theme":"Дорога","story_shelf":"Любовные сцены","conflict_key":"пустая-трасса-против-нужды-в-голосе","image_key":"луна-на-дне-ночного-кювета","turn_key":"попутчик-оказался-одноклассником","hook_key":"golos-vazhnee-marshruta","sort_order":"1429","original_key":"konstantin-vanshenkin|nochnaya-doroga","author_name":"Константин Ваншенкин","original_title":"Ночная дорога","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/vanshenkin/nochnaya-doroga/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2012.","music_adaptations":[],"source_synopsis":"Герой идёт ночной дорогой, бодрит себя, слушает скрип ели и уханье филина в чаще — весь мир будто спит или искусно притворяется. Мир огромен, путь далёк, и от этой тишины щемит грусть. Из всего этого рождается простое человеческое заклинание: друзья, давайте видеться почаще.","main_image":"луна на дне ночной канавы"},{"title":"Бригада невоспетых","full_story":"Кочевая ветеринарная бригада из трёх человек колесит по фермерским хозяйствам, где никто не справляется с буйными быками: их ремесло — старинное, суровое и никем не воспетое, о нём даже песен нет. Хозяин фермы сначала смотрит свысока, потом молча подаёт чай, увидев, как спокойно и почти ритуально работает старший. Буйный бык наутро идёт к водопою ровным шагом, а бригада грузит инструменты и едет к следующему стаду — без фанфар, по грязной дороге.","hero_pov":"Старший невоспетой бригады","central_conflict":"Ферма зовёт на подмогу, но не собирается благодарить тех, чьё ремесло считает грязным.","emotional_arc":"От свысока к молчаливому уважению и дальше в дорогу","ending_direction":"Поворот: хозяин молча ставит чай — а бригада уже едет к следующему стаду","hook_direction":"Мы те, кто укрощает","genres":["Кантри","Рок"],"moods":["Решимость","Сила"],"energy":"Средняя","themes":["дорога","работа"],"generator_brief":"Дорожное кантри-рок с банджо и скрипкой; куплеты — грязь и работа, припев — бригада едет дальше.","generator_story":"Кочевая бригада ветеринаров усмиряет буйных быков старинным ремеслом, о котором нет ни песен; хозяин фермы, смотревший свысока, молча подаёт чай, а бригада едет к следующему стаду.","primary_genre":"Кантри","primary_mood":"Решимость","primary_theme":"дорога","story_shelf":"Люди и животные","conflict_key":"грязное-ремесло-против-незаменимой-работы","image_key":"зола-подсолнуха-на-ране","turn_key":"хозяин-молча-ставит-чай","hook_key":"my-te-kto-ukroshchaet","sort_order":"1430","original_key":"sergej-markov|kastratory-bykov","author_name":"Сергей Марков","original_title":"Кастраторы быков","original_language":"Russian","origin_country":"Россия","original_year":"1924","source_url":"https://rustih.com/sergej-markov-kastratory-bykov/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1979.","music_adaptations":[],"source_synopsis":"Ода забытому бродячему ремеслу: веками никем не воспетые суровые кастраторы быков, «невольные бродяги и поэты», с почерневшими руками и мешком тяжёлых ножей у седла. Ремесло описано как древний обряд: к буйному быку приступает «суровый жрец неотвратимой требы», рану присыпают золой подсолнуха. После обряда бык сменяет весенний буйный бег на мерный шаг к стадам и водопою.","main_image":"зола подсолнуха на ране быка"},{"title":"Сказка про то, как я всех спас","full_story":"Ночной сторож общежития Лёва вечерами сочиняет в голове героические сюжеты: вот он выносит из подворотни замерзающего щенка, вот вытаскивает из проруби девчонку, вот у них вырастает гениальный сын. Утром в подворотне пусто, и Лёва признаётся напарнику: всё это он «спас» сидя на стуле у окна, пока мимо шла реальность. Со следующей смены он встаёт с тёплого стула за час до рассвета и первым выходит во двор — теперь спасать по-настоящему.","hero_pov":"Сторож, спасавший всех не вставая","central_conflict":"Сказка в голове блестяща и безопасна, а для настоящего спасения нужно встать со стула в холод.","emotional_arc":"От красивой фантазии через горькое признание к первому реальному шагу","ending_direction":"Поворот: он впервые встаёт затемно и выходит во двор до того, как понадобится спасать","hook_direction":"Встану и сделаю","genres":["Хип-хоп","Альтернатива"],"moods":["Вина","Надежда"],"energy":"Средняя","themes":["выбор","животные"],"generator_brief":"Пыльный хип-хоп с лоу-фай пианино и скрипом стула; куплеты — буйные грёзы, припев — честный призыв встать.","generator_story":"Ночной сторож сочиняет в голове, как спасает пса и тонущую девушку, но признаётся: весь вечер он не вставал со стула; со следующей смены он поднимается затемно и выходит во двор по-настоящему.","primary_genre":"Хип-хоп","primary_mood":"Вина","primary_theme":"выбор","story_shelf":"Люди и животные","conflict_key":"фантазия-против-неподвижности","image_key":"стул-у-окна-ночной-смены","turn_key":"подъём-затемно-вместо-сказки","hook_key":"vstanu-i-sdelayu","sort_order":"1431","original_key":"sergej-narovchatov|pes-devchonka-i-poet","author_name":"Сергей Наровчатов","original_title":"Пес, девчонка и поэт","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://rustih.com/sergej-narovchatov-pes-devchonka-i-poet/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1981.","music_adaptations":[],"source_synopsis":"Герой, возвращаясь вечерами из «знакомого места», в воображении совершает подвиги: спасает из подворотни замерзающего пса, вытаскивает из реки бросившуюся девчонку, а у той потом рождается чудесный ребёнок, великий человек. В финале признаётся: давно бросил пить, весь вечер не вставал со стула — и всё вышло наоборот: пёс замёрз, девчонка утонула, великий человек не родился. Ироничная притча о добрых делах, случившихся только в пьяной голове.","main_image":"стул у окна, с которого никто не встал"},{"title":"Пальто для попутчицы","full_story":"Водитель междугородного автобуса слышит с задних сидений плач: дверью порвало единственное пальто маленькой девочки, которая едет к опекунам одна. До зарплаты далеко, в кошельке деньги на неделю, но на конечной он ведёт её в магазин и покупает новое пальто. Девочка впервые за рейс улыбается и засыпает на обратной петле. Песня о том, что доброта — это тоже маршрут туда и обратно.","hero_pov":"водитель междугородного автобуса","central_conflict":"у водителя деньги на неделю — у ребёнка рваное пальто и никого роднее","emotional_arc":"от раздражения ночного рейса к тихой радости отданного","ending_direction":"обратный рейс едет теплее: она спит в новом пальто, он забывает про кошелёк","hook_direction":"тепло можно передать с водителем","genres":["Кантри","Фолк"],"moods":["Нежность","Тепло"],"energy":"Средняя","themes":["Детство","поддержка","дорога"],"generator_brief":"Дорожное кантри с губной гармошкой: куплеты — ночной автобус и плач с задних сидений, припев — покупка пальто на конечной, бридж — спящий ребёнок на обратной петле.","generator_story":"Водитель междугороднего автобуса видит, как дверью порвало единственное пальто маленькой сироты. До зарплаты далеко, но он покупает ей новое пальто, и обратный рейс выходит тёплым.","primary_genre":"Кантри","primary_mood":"Нежность","primary_theme":"Детство","story_shelf":"Трагические истории","conflict_key":"последние-деньги-против-рваного-пальто","image_key":"новое-пальто-перед-обратным-рейсом","turn_key":"ребёнок-улыбается-на-петле","hook_key":"тепло-едет-с-водителем","sort_order":"1432","original_key":"william-wordsworth|alice-fell","author_name":"Уильям Вордсворт","original_title":"Alice Fell, or Poverty","original_language":"английский","origin_country":"Великобритания","original_year":"1807","source_url":"https://en.wikisource.org/wiki/Poems,_in_Two_Volumes_(Wordsworth,_1807)/Volume_1/Alice_Fell","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1850.","music_adaptations":[],"source_synopsis":"Пассажир почтового дилижанса слышит в ночи детский плач: у сироты-девочки единственное пальто намотало и изорвало на спицах колеса. Он сходит, отводит ребёнка в город, покупает ей новое пальто и продолжает путь, растроганный тем, как быстро детское горе сменяется радостью.","main_image":"изорванное о ступицу детское пальто и новая накидка к утреннему рейсу"},{"title":"Свет в комнате сына","full_story":"Мать семь лет зажигает свет в комнате сына, уехавшего без следа: ни писем, ни могилы, только пустой ящик почты. Соседям она говорит «скоро вернётся», себе — ничего. Однажды в ящике появляется открытка без подписи и обратного адреса: он жив, он помнит, но молчит. Она не бросается искать — она просто оставляет свет гореть и дальше: ждать стало её способом любить.","hero_pov":"мать, чей сын пропал семь лет назад","central_conflict":"семь лет молчания против материнской надежды, которую нельзя ни похоронить, ни дожить","emotional_arc":"от глухого отчаяния к тихому примирению с неизвестностью","ending_direction":"открытка без подписи: она понимает, что ждать — её язык, и отвечает ему светом","hook_direction":"оставь свет — он увидит из любой темноты","genres":["Блюз","Баллада"],"moods":["Надежда","Тревога"],"energy":"Низкая","themes":["Дом","ожидание","семья"],"generator_brief":"Медленный блюз с органом: куплеты — пустой почтовый ящик и соседские «скоро вернётся», припев — свет в окне, финал — безымянная открытка и отказ гасить лампу.","generator_story":"Мать семь лет держит свет в комнате пропавшего сына. В ящике появляется открытка без подписи: он жив, но молчит. Она не требует слов и отвечает ему светом в окне.","primary_genre":"Блюз","primary_mood":"Надежда","primary_theme":"Дом","story_shelf":"Трагические истории","conflict_key":"надежда-против-семилетнего-молчания","image_key":"свет-в-окне-комнаты-сына","turn_key":"открытка-без-подписи","hook_key":"оставь-свет-он-увидит","sort_order":"1433","original_key":"william-wordsworth|the-affliction-of-margaret","author_name":"Уильям Вордсворт","original_title":"The Affliction of Margaret","original_language":"английский","origin_country":"Великобритания","original_year":"1807","source_url":"https://en.wikisource.org/wiki/Poems,_in_Two_Volumes_(Wordsworth,_1807)/Volume_1/The_Affliction_of_Margaret","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1850.","music_adaptations":[],"source_synopsis":"Мать годами ждёт пропавшего сына: ни письма, ни могилы, ни вести. Её мечется между надеждой и отчаянием — то она видит его живым и счастливым, то мёртвым; неопределённость съедает её, но и убить надежду она не в силах.","main_image":"свет в комнате сына, который горит седьмой год"},{"title":"Стадо брата","full_story":"Моряк возвращается в долину после долгих лет в плавании — его считали мёртвым. Старый пастор, не узнавая, рассказывает ему о его брате-пастухе: тот ждал корабль на скалах и сорвался в темноте. Всю ночь моряк слушает про свою семью как про чужую, а на рассвете впервые не поднимается на борт: он берёт братову отару и остаётся на склоне. Песня о возвращении, которое опоздало к одному человеку, но успело к его делу.","hero_pov":"моряк, вернувшийся с многолетнего рейса","central_conflict":"живой возвращается туда, где память держит погибшего, и его место занято горем","emotional_arc":"от чужой отрешённости к принятию вины и корней","ending_direction":"он остаётся: вместо горизонта — склон, вместо палубы — чужая ставшая своей отара","hook_direction":"кто-то должен пасти то, что осталось","genres":["Баллада","Фолк"],"moods":["Вина","Светлая грусть"],"energy":"Средняя","themes":["море","возвращение","семья"],"generator_brief":"Горная баллада с акустикой и волынкой вдали: куплеты — рассказ пастора и молчание моряка, припев — скалы, с которых смотрели на море, финал — решение остаться.","generator_story":"Моряк возвращается с долгого рейса и от старого пастора слышит, как его брат ждал его на скалах и сорвался вниз. Он слушает про себя как про чужого, а наутро берёт братову отару.","primary_genre":"Баллада","primary_mood":"Вина","primary_theme":"море","story_shelf":"Трагические истории","conflict_key":"возвращение-живого-к-памяти-погибшего","image_key":"отара-на-пустом-склоне","turn_key":"моряк-берёт-посох-пастуха","hook_key":"стадо-ждёт-своего-пастуха","sort_order":"1434","original_key":"william-wordsworth|the-brothers","author_name":"Уильям Вордсворт","original_title":"The Brothers","original_language":"английский","origin_country":"Великобритания","original_year":"1800","source_url":"https://en.wikisource.org/wiki/Poems_(Wordsworth,_1815)/Volume_1/The_Brothers","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1850.","music_adaptations":[],"source_synopsis":"В долину возвращается моряк, проплававший годы и считавшийся погибшим. Старый пастор не узнаёт его и рассказывает ему историю его же брата-пастуха: тот тосковал по ушедшему в море, вечерами смотрел со скал на горизонт и сорвался в пропасть. Моряк выслушивает судьбу своей семьи как чужую.","main_image":"отара на горном склоне, где раньше стоял пастух"},{"title":"Одна кружка на перевале","full_story":"Дальнобойщик пережидает грозу на перевале и заходит в придорожную корчму «на одну кружку» — выходит полночь и третья. Пока он спит в спальнике, его жена — штурман этого рейса — пересаживается за руль и ведёт фуру по мокрому серпантину. Утром он просыпается на разгруженном дворе с фингалом совести и горящим в кабине термосом. Песня о том, что за каждым «доехал» кто-то сидел за рулём, пока ты отдыхал.","hero_pov":"дальнобойщик, пережидающий грозу","central_conflict":"гроза на перевале и лишняя кружка против утреннего срока разгрузки","emotional_arc":"от бравады к стыду и тёплой благодарности","ending_direction":"он просыпается на разгруженном дворе — рейс спасён не им","hook_direction":"за рулём — та, что тебя ждёт","genres":["Кантри","Рок"],"moods":["Драйв","Тепло"],"energy":"Высокая","themes":["Дорога","семья","животные"],"generator_brief":"Разгонное кантри-шутливое: куплеты — гроза, корчма и «одна кружка», припев — ночная езда по серпантину, финал — утро на разгруженном дворе и термос.","generator_story":"Дальнобойщик пережидает грозу на перевале и берёт лишнюю кружку в придорожной корчме. Пока он спит, жена ведёт фуру по серпантину, и он просыпается уже на разгруженном дворе.","primary_genre":"Кантри","primary_mood":"Драйв","primary_theme":"Дорога","story_shelf":"Юмор: семейные драмы","conflict_key":"гроза-и-лишняя-кружка-против-срока","image_key":"фура-под-молнией-на-серпантине","turn_key":"жена-ведёт-фуру-пока-он-спит","hook_key":"за-рулём-та-что-ждёт","sort_order":"1435","original_key":"william-wordsworth|the-waggoner","author_name":"Уильям Вордсворт","original_title":"The Waggoner","original_language":"английский","origin_country":"Великобритания","original_year":"1819","source_url":"https://www.gutenberg.org/ebooks/12383","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1850.","music_adaptations":[],"source_synopsis":"Мокко-героическая поэма о возчике Бенджамине, который ведёт фуру через грозовой горный перевал. У придорожной корчмы «одна кружка» превращается в ночь, и наполовину спящего возчика с фурой до города доводит верный пони, подаренный женой, — человеческая слабость против терпения зверя и стихии.","main_image":"фура под молнией на серпантине перевала"},{"title":"Урок зрения","full_story":"Мужчина возвращается к дому детства и стоит у старого куста, где сестра много лет назад показала ему воробьиное гнездо — и научила видеть: птиц, свет, чужие лица. Сестры давно нет рядом, но её урок работает в нём каждый день. Теперь он приводит к этому кусту свою дочь и повторяет ей то же самое. Песня о наследстве, которое не оформляют на бумаге: дар зрения передаётся из рук в руки.","hero_pov":"взрослый сын у куста детства","central_conflict":"город приучил смотреть не видя — и только старый куст возвращает зрение","emotional_arc":"от суеты к благодарности и передаче дара дальше","ending_direction":"куст пуст — но теперь смотрит уже дочь, и воробьи возвращаются","hook_direction":"смотри, как учила она","genres":["Регги","Лоу-фай"],"moods":["Тепло","Нежность"],"energy":"Низкая","themes":["Детство","семья","животные"],"generator_brief":"Тёплое семейное регги с флейтой: куплеты — куст, сестра и детство, припев — «смотри», бридж — дочь у того же куста, финал — вернувшиеся воробьи.","generator_story":"Мужчина возвращается к дому детства и вспоминает, как сестра научила его видеть воробьёв в кусте у крыльца. Он приводит туда дочь и передаёт ей этот дар зрения.","primary_genre":"Регги","primary_mood":"Тепло","primary_theme":"Детство","story_shelf":"Люди и животные","conflict_key":"город-гасит-зрение-сестры-возвращают","image_key":"куст-с-воробьиной-песней-у-крыльца","turn_key":"дочь-смотрит-вместо-него","hook_key":"смотри-как-учила-она","sort_order":"1436","original_key":"william-wordsworth|the-sparrows-nest","author_name":"Уильям Вордсворт","original_title":"The Sparrow's Nest","original_language":"английский","origin_country":"Великобритания","original_year":"1807","source_url":"https://en.wikisource.org/wiki/Poems,_in_Two_Volumes_(Wordsworth,_1807)/Volume_2/The_Sparrow%27s_Nest","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1850.","music_adaptations":[],"source_synopsis":"Короткое стихотворение о кусте у дома детства, где жило воробьиное гнездо: поэт благодарит сестру — она подарила ему глаза и уши, научила замечать птиц и свет. Взрослый смотрит на мир так, как его когда-то научила сестра.","main_image":"куст у крыльца, в котором каждый год снова воробьи"},{"title":"Штурман с крыльца","full_story":"Турист ломает ногу накануне большого похода, и друзья уходят в горы без него. Из кресла на крыльце он превращается в диспетчера маршрута: карты, спутниковые снимки, прогноз ветра, подсказки по тропам — группа идёт буквально по его голосу. К закату он встречает их на крыльце с перевязанной ногой и знает маршрут лучше всех прошедших. Песня о том, что из любого плена есть ход — воображение, и оно доводит до настоящего заката.","hero_pov":"турист с гипсом на крыльце","central_conflict":"сломанная нога против похода, которого ждали год","emotional_arc":"от зависти и обиды к вдохновению и общей победе","ending_direction":"друзья возвращаются с закатом — и приносят ему половину каждого вида","hook_direction":"закат доходит и до крыльца","genres":["Синтвейв","Электропоп"],"moods":["Вдохновение","Тепло"],"energy":"Высокая","themes":["Дом","дружба","природа"],"generator_brief":"Восходящий синтвейв с панорамными падами: куплеты — гипс и пустая тропа, припев — полёт воображения над хребтом, финал — встреча друзей на закате.","generator_story":"Турист ломает ногу перед большим походом, и друзья уходят без него. Из кресла он ведёт их по карте и погоде, а к закату встречает на крыльце, зная маршрут лучше всех.","primary_genre":"Синтвейв","primary_mood":"Вдохновение","primary_theme":"Дом","story_shelf":"Юмор: семейные драмы","conflict_key":"гипс-против-похода-года","image_key":"кресло-с-видом-на-весь-маршрут","turn_key":"закат-доходит-до-крыльца","hook_key":"провожу-вас-не-вставая","sort_order":"1437","original_key":"samuel-coleridge|this-lime-tree-bower-my-prison","author_name":"Сэмюел Тейлор Кольридж","original_title":"This Lime-Tree Bower My Prison","original_language":"английский","origin_country":"Великобритания","original_year":"1800","source_url":"https://en.wikisource.org/wiki/Sibylline_Leaves_(Coleridge)/This_Lime_Tree_Bower_My_Prison","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1834.","music_adaptations":[],"source_synopsis":"Разговорное стихотворение: хозяин, застрявший из-за травмы под липой в саду, мысленно сопровождает друзей в их прогулке по холмам и долине — по скалам, через рощу, к закату. Воображение доводит его до тех же видов, и вечером он встречает друзей уже не пленником, а соучастником их дня.","main_image":"кресло под липой, из которого виден весь маршрут"},{"title":"Реабилитация соловья","full_story":"Друг годами злился на соловья за окном больницы: под его песню он терял близких на ночных дежурствах. Второй друг уговаривает его выйти ночью на мостик и послушать птицу заново — без старой обиды. Они слушают до рассвета, и птица, которую один человек зря считал вестником горя, оказывается просто голосом ночи. Песня о том, что иногда нужно официально простить того, кто ни в чём не виноват.","hero_pov":"друг-посредник на ночном мостике","central_conflict":"старая обида на ни в чём не виноватую птицу против общего рассвета","emotional_arc":"от глухой боли к снятой клевете и лёгкости","ending_direction":"они слушают до рассвета — и птице возвращается доброе имя","hook_direction":"она пела не о горе","genres":["Эмбиент","Лоу-фай"],"moods":["Нежность","Спокойствие"],"energy":"Низкая","themes":["прощение","Ночь","животные"],"generator_brief":"Ночной эмбиент с полевой записью птицы: куплеты — больничные ночи и обида, припев — чистое пение соловья, финал — два голоса на рассвете.","generator_story":"Друг годами злился на соловья за окном больницы, где он терял близких. Второй друг уговаривает послушать птицу заново: они снимают с неё старую обиду и слушают до рассвета.","primary_genre":"Эмбиент","primary_mood":"Нежность","primary_theme":"прощение","story_shelf":"Люди и животные","conflict_key":"обида-на-птицу-против-рассвета","image_key":"мостик-над-ночной-рекой","turn_key":"песня-оправдана-к-утру","hook_key":"она-пела-не-о-горе","sort_order":"1438","original_key":"samuel-coleridge|the-nightingale","author_name":"Сэмюел Тейлор Кольридж","original_title":"The Nightingale: A Conversation Poem","original_language":"английский","origin_country":"Великобритания","original_year":"1798","source_url":"https://en.wikisource.org/wiki/Sibylline_Leaves_(Coleridge)/The_Nightingale","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1834.","music_adaptations":[],"source_synopsis":"Ночная беседа у моста: собеседники спорят о соловье, которого поэты по инерции записали в «печальную» птицу. Автор призывает снять с птицы чужую клевету — в природе нет ничего меланхоличного — и заканчивает колыбельной своему младенцу, которого хочет вырастить другом природы.","main_image":"мостик над ночной рекой, где двое слушают одну птицу"},{"title":"Мясник сносит цех","full_story":"Мясник районной лавки — тихий гигант с самым мягким сердком в квартале — теряет жену: врачи сказали «не успели». Ночью он приходит в свой цех и разбирает его до кирпича: крюки, пилы, лотки — дело всей жизни складывается у стены грудой железа. Утром лавка не закрывается: в пустой витрине стоят цветы, которые она любила. Песня о горе, которое ломает не человека, а то, чем человек больше не может заниматься.","hero_pov":"мясник районной лавки","central_conflict":"дело всей жизни против горя, с которым нельзя резать мясо","emotional_arc":"от онемения к яростному слому и тихой новой витрине","ending_direction":"бойни больше нет — в витрине остались цветы, и лавка открывается утром","hook_direction":"крюки не пережили её","genres":["Панк","Альтернативный рок"],"moods":["Злость","Боль"],"energy":"Взрывная","themes":["Дом","Потеря","работа"],"generator_brief":"Тяжёлый панк с рваным ритмом разборки: куплеты — тихий гигант и его цех, взрыв — ночной слом, финал — утренняя витрина с цветами на чистом риффе.","generator_story":"Мясник районной лавки теряет жену: врачи не успели. Ночью он разбирает свою бойню до кирпича, а утром оставляет в пустой витрине цветы, которые она любила больше всего.","primary_genre":"Панк","primary_mood":"Злость","primary_theme":"Дом","story_shelf":"Трагические истории","conflict_key":"горе-против-дела-всей-жизни","image_key":"разобранная-бойня-к-рассвету","turn_key":"витрина-живая-под-цветы","hook_key":"крюки-не-пережили-её","sort_order":"1439","original_key":"edwin-arlington-robinson|reuben-bright","author_name":"Эдвин Арлингтон Робинсон","original_title":"Reuben Bright","original_language":"английский","origin_country":"США","original_year":"1897","source_url":"https://www.americanpoems.com/poets/robinson/reuben-bright","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1935.","music_adaptations":[],"source_synopsis":"Короткая баллада о мяснике с самым мягким сердцем в городе. Когда врачи «забирают» его жену, он молча уходит — и наутро разбирает по брёвнам собственную бойню, ту, что кормила его всю жизнь.","main_image":"разобранная до кирпича бойня и одна цветочная витрина"},{"title":"Номер выходит в срок","full_story":"Редактор маленькой городской газеты печатает колонку заступничества за тех, кого в городе все осудили. Ночью толпа «достойных граждан» громит типографию: станок на боку, шрифт в грязи, сам он — в дёгте. Наутро приходят наборщики, и втроём, ссаживая пальцы, они собирают станок заново. Номер выходит в срок — тоньше обычного, на чистой бумаге, с той же колонкой. Песня о команде, которая не даёт слову лечь в грязь.","hero_pov":"редактор маленькой городской газеты","central_conflict":"разбитый за ночь станок против завтрашнего срока выхода","emotional_arc":"от унижения к упрямой соборной злости и выпуску","ending_direction":"номер выходит в срок, и колонка напечатана снова","hook_direction":"станок собирают те, кто его кормит","genres":["Хип-хоп","Рэп"],"moods":["Протест","Решимость"],"energy":"Высокая","themes":["команда","голос","работа"],"generator_brief":"Уличный хип-хоп с битом печатного станка: куплеты — погром и дёготь, припев — «номер выходит в срок», финал — чистая бумага и та же колонка.","generator_story":"Редактор районной газеты печатает заступничество за осуждённых, и толпа громит типографию. Наутро наборщики собирают станок заново, и номер выходит в срок — тоньше, но на чистой бумаге.","primary_genre":"Хип-хоп","primary_mood":"Протест","primary_theme":"команда","story_shelf":"Трагические истории","conflict_key":"разбитый-станок-против-срока","image_key":"рассыпанный-и-собранный-шрифт","turn_key":"номер-тоньше-но-в-срок","hook_key":"станок-собирают-те-кто-кормит","sort_order":"1440","original_key":"edgar-lee-masters|carl-hamblin","author_name":"Эдгар Ли Мастерс","original_title":"Carl Hamblin","original_language":"английский","origin_country":"США","original_year":"1915","source_url":"https://www.poetryfoundation.org/poems/45928/carl-hamblin","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1950.","music_adaptations":[],"source_synopsis":"Эпитафия из «Спун-Ривер»: редактор провинциальной газеты напечатал в день казни строку заступничества за осуждённых. Ночью толпа разгромила его типографию, а его самого вымазала в дёготе и перьях. Голос из могилы говорит о цене правды в городке, где все друг другу родственники.","main_image":"рассыпанный по полу шрифт, который к утру снова собран"},{"title":"Два камня, один куст","full_story":"Правнук приходит на старое кладбище и читает два соседних камня: прадед пишет, что жена выпила его жизнь; прабабка — что муж сломал её. Семейная память хранит обе версии, и внуки десятилетиями передают их как войну. Правнук сажает между камнями один куст — живой, выше обеих надписей. Песня о том, что посмертный суд нельзя выиграть, но можно прекратить.","hero_pov":"правнук на семейном кладбище","central_conflict":"две правды об одном браке, между которыми не прожить потомкам","emotional_arc":"от растерянности между лагерями к мирному жесту","ending_direction":"куст выше надписей — спор заканчивается не победой, а тишиной","hook_direction":"цветок важнее надписи","genres":["Блюз","Фолк"],"moods":["Вина","Светлая грусть"],"energy":"Низкая","themes":["прощение","семья","память"],"generator_brief":"Тихий блюз с двуголосием: куплеты — голос прадеда и прабабки по очереди, припев — правнук между камнями, финал — посаженный куст.","generator_story":"Правнук читает на кладбище два соседних камня: прадед и прабабка винят друг друга в съеденной жизни. Он сажает между ними один куст, и их правды перестают враждовать.","primary_genre":"Блюз","primary_mood":"Вина","primary_theme":"прощение","story_shelf":"Трагические истории","conflict_key":"две-правды-об-одном-браке","image_key":"соседние-надгробия-и-куст","turn_key":"куст-выше-обеих-надписей","hook_key":"цветок-важнее-надписи","sort_order":"1441","original_key":"edgar-lee-masters|fletcher-mcgee","author_name":"Эдгар Ли Мастерс","original_title":"Fletcher McGee","original_language":"английский","origin_country":"США","original_year":"1915","source_url":"https://poets.org/poem/fletcher-mcgee","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1950.","music_adaptations":[],"source_synopsis":"Одна из парных эпитафий «Спун-Ривер»: мужская версия брака, в которой каждый из супругов называет другого пожирателем своей жизни. Два соседних надгробия хранят две несовместимые правды об одной общей молодости.","main_image":"два соседних камня и один куст между ними"},{"title":"Не плачу за расстояние","full_story":"Уборщица Альберта получает счёт за межгород: компания уверяет, что она «согласовала» разговоры. Согласна она только в одном — платить за минуты голоса сына, который за тысячу вёрст. С бюджетом на неделю в кармане она идёт спорить в контору и выходит оттуда, не потеряв ни гордости, ни сына на проводе. Песня о достоинстве, которое не измеряется тарифом.","hero_pov":"уборщица Альберта у окошка телефонной конторы","central_conflict":"счёт за межгород против гордости и последних денег до пятницы","emotional_arc":"от возмущения к язвительной победе","ending_direction":"она платит за голос, а за расстояние не платит — и везёт сыну пирог","hook_direction":"голос сына не тарифицируется","genres":["Регги","Блюз"],"moods":["Уверенность","Ирония"],"energy":"Высокая","themes":["дорога","семья","самоценность"],"generator_brief":"Упругое регги с медным басом: куплеты — спор с конторой и «я не заказывала», припев — его голос на проводе, финал — победа и пирог в почтовый ящик.","generator_story":"Уборщица Альберта получает счёт за межгород, которого не заказывала. Компания давит, но она платит только за минуты разговора с сыном за тысячу вёрст: за расстояние не платит.","primary_genre":"Регги","primary_mood":"Уверенность","primary_theme":"дорога","story_shelf":"Юмор: семейные драмы","conflict_key":"межгород-против-достоинства-бюджета","image_key":"счёт-на-тысячу-вёрст","turn_key":"платит-за-голос-не-за-километры","hook_key":"голос-не-тарифицируется","sort_order":"1442","original_key":"langston-hughes|madam-and-the-phone-bill","author_name":"Лэнгстон Хьюз","original_title":"Madam and the Phone Bill","original_language":"английский","origin_country":"США","original_year":"1944","source_url":"https://poets.org/poem/madam-and-phone-bill","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1967.","music_adaptations":[],"source_synopsis":"Монолог из цикла о миссис Альберте Джонсон: ей приходит счёт за междугородние переговоры, которые она «не заказывала». С достоинством и язвительным юмором она отбивается от компании, не теряя лица и не отказываясь от того единственного, ради чего звонки были.","main_image":"телефонный счёт на тысячу вёрст"},{"title":"Ночная смена меди","full_story":"Трубач выходит на ночную смену в клуб с усталостью, которую не нажил сам: в ней — дедовы дороги, чужие города, всё, что семья несла поколениями. Каждый сет он начинает с этой тяжести за пазухой, и каждый соло проводит её через медь. К последнему номеру темнота в трубе выдувается наружу чистой нотой — и зал встаёт. Песня о музыканте, который не прячет наследство, а играет его.","hero_pov":"трубач ночного клуба","central_conflict":"последний сет ночи против усталости, которую он не наживал","emotional_arc":"от свинцовой усталости к очищающему соло и подъёму зала","ending_direction":"последняя нота сета выходит чистой — беда переработана в звук","hook_direction":"ночь слушает медь","genres":["Джаз","Соул"],"moods":["Боль","Сила"],"energy":"Высокая","themes":["Ночь","музыка","память"],"generator_brief":"Поздний джаз с живой трубой: куплеты — усталость и память рода, припев — восходящее соло, финал — чистая нота и встающий зал.","generator_story":"Трубач играет ночной сет в клубе, и в соло прорывается память его рода. Он не глушит её, а проводит через медь, и последний звук сета встаёт чистой нотой из темноты.","primary_genre":"Джаз","primary_mood":"Боль","primary_theme":"Ночь","story_shelf":"Трагические истории","conflict_key":"чужая-усталость-против-последнего-сета","image_key":"труба-с-памятью-поколений","turn_key":"тяжелый-воздух-выдувается-чистой-нотой","hook_key":"ночь-слушает-медь","sort_order":"1443","original_key":"langston-hughes|trumpet-player","author_name":"Лэнгстон Хьюз","original_title":"Trumpet Player","original_language":"английский","origin_country":"США","original_year":"1942","source_url":"https://allpoetry.com/Trumpet-Player","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1967.","music_adaptations":[],"source_synopsis":"Трубач в ночном клубе играет сет, измученный и великий. В его соло прорывается память поколений — усталость, унаследованная чужими бедами, — и музыка перерабатывает её в чистую, светлую ноту.","main_image":"медь трубы, в которой слышно целые поколения"},{"title":"Снимаю проклятия","full_story":"Сын белого отца и чёрной матери всю жизнь злился на обоих: отец умер в большом доме, мать — в лачуге на другом конце дороги. На похоронах матери он вслух забирает назад все свои проклятия — оба подарили ему жизнь на этом перекрёстке. Он строит свой дом ровно на середине дороги между тем и другим. Песня о прощении родителей, которое освобождает место для собственной жизни.","hero_pov":"сын на перекрёстке двух семей","central_conflict":"злость на двоих родителей против собственной крови, в которой оба","emotional_arc":"от бунта к забранному проклятию и своему месту","ending_direction":"он строит дом на середине дороги — не в том и не в другом крае","hook_direction":"я не дом и не лачуга","genres":["Блюз","Соул"],"moods":["Освобождение","Светлая грусть"],"energy":"Средняя","themes":["прощение","семья","самопринятие"],"generator_brief":"Полуакустический блюз: куплеты — два конца дороги и похороны, припев — снятое проклятие, финал — закладка своего дома на середине.","generator_story":"Сын белого отца и чёрной матери злился на обоих: отец умер в большом доме, мать — в лачуге. Он забирает проклятия назад и строит свой дом на середине дороги.","primary_genre":"Блюз","primary_mood":"Освобождение","primary_theme":"прощение","story_shelf":"Трагические истории","conflict_key":"проклятия-родителям-против-крови","image_key":"дом-на-середине-дороги","turn_key":"проклятия-забираются-назад","hook_key":"я-не-дом-и-не-лачуга","sort_order":"1444","original_key":"langston-hughes|cross","author_name":"Лэнгстон Хьюз","original_title":"Cross","original_language":"английский","origin_country":"США","original_year":"1926","source_url":"https://www.poetryfoundation.org/poems/150989/cross","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1967.","music_adaptations":[],"source_synopsis":"Лирический герой — сын белого отца и чёрной матери. Он злится на обоих родителей и проклинает их, но тут же забирает проклятия назад: отец умер в большом доме, мать — в лачуге, а ему самому предстоит решить, где закончится его собственная дорога.","main_image":"большой дом на одном краю дороги и лачуга на другом"},{"title":"Инструкция к похоронам","full_story":"Старый плотник оставляет городу завещание-инструкцию: на его похоронах — ни венков, ни лакированного катафалка, ни речей над головой. Только простой грузовичок, рабочие ботинки и дорога через весь город, где он прожил жизнь. Город ворчит «так не хоронят», но выполняет букву списка. На маршруте без оркестра впервые слышно, как звучат шаги. Песня о последней дороге, которую человек имеет право провести по-своему.","hero_pov":"старый плотник, оставивший завещание","central_conflict":"пышный ритуал города против последней воли простого человека","emotional_arc":"от ворчания города к тихой честности обряда","ending_direction":"без оркестра слышны шаги — и это самые честные похороны в городе","hook_direction":"проще — значит честнее","genres":["Панк","Фолк"],"moods":["Освобождение","Решимость"],"energy":"Высокая","themes":["Дорога","память","свобода"],"generator_brief":"Прямой панк-марш без украшений: куплеты — пункты завещания, припев — дорога через город, финал — тишина и шаги вместо оркестра.","generator_story":"Старый плотник оставляет завещание: на его похоронах ни венков, ни катафалка, ни речей. Город ворчит, что так не хоронят, но выполняет — и без оркестра слышно шаги.","primary_genre":"Панк","primary_mood":"Освобождение","primary_theme":"Дорога","story_shelf":"Трагические истории","conflict_key":"пышный-ритуал-против-последней-воли","image_key":"простая-телега-вместо-катафалка","turn_key":"без-оркестра-слышны-шаги","hook_key":"проще-значит-честнее","sort_order":"1445","original_key":"william-carlos-williams|tract","author_name":"Уильям Карлос Уильямс","original_title":"Tract","original_language":"английский","origin_country":"США","original_year":"1921","source_url":"https://allpoetry.com/poem/8501095-Tract-by-William-Carlos-Williams","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1963.","music_adaptations":[],"source_synopsis":"Стихотворение-наставление: поэт учит земляков, как провести его собственные похороны — без глянцевых экипажей, подушек и оркестра, на простых телегах, обычной обувью, по-человечески и честно. Протест против похоронного парада, который заглушает саму утрату.","main_image":"простые сани вместо лакированного катафалка"},{"title":"Кто моет ваши яхты","full_story":"В день большой регаты мойщиков корпусов и причальных рабочих выгоняют из марины за ограду — чтобы не портили картинку для гостей. К вечеру налетает шторм: причалы ломает, дорогие корпуса бьёт о бетон. Спасают флот те самые руки, которые утром красили борта и которым не нашлось места в кадре. Песня о том, что вода одна на всех — просто не всех в неё пускают.","hero_pov":"мойщик корпусов из службы марины","central_conflict":"глянец регаты против тех, кто красит и чинит эти корпуса","emotional_arc":"от униженного гнева к штормовой работе и молчаливому счёту","ending_direction":"после шторма яхты целы — и спасены руками, что утром были лишними","hook_direction":"после шторма все вёсла равны","genres":["Техно","Метал"],"moods":["Злость","Протест"],"energy":"Взрывная","themes":["море","город","работа"],"generator_brief":"Холодное техно с ударной петлёй: куплеты — ограда марины и яркий глянец, припев — шторм, финал — рабочие руки спасают чужой флот.","generator_story":"В день регаты мойщиков корпусов выгоняют из марины за ограду. К вечеру шторм ломает причалы, и яхты богачей спасают те руки, что утром красили им борта.","primary_genre":"Техно","primary_mood":"Злость","primary_theme":"море","story_shelf":"Трагические истории","conflict_key":"глянец-регаты-против-тех-кто-в-воде","image_key":"яхты-над-толпой-под-килем","turn_key":"шторм-уравнивает-причалы","hook_key":"после-шторма-вёсла-равны","sort_order":"1446","original_key":"william-carlos-williams|the-yachts","author_name":"Уильям Карлос Уильямс","original_title":"The Yachts","original_language":"английский","origin_country":"США","original_year":"1935","source_url":"https://allpoetry.com/poem/14327735-The-Yachts-by-William-Carlos-Williams","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1963.","music_adaptations":[],"source_synopsis":"Стихотворение о парусной регате богатых: отточенные яхты режут воду залива, а под зеркальной поверхностью изображены тела простых людей — вода как толпа, которую не спрашивают. Глянец привилегии против тех, кто всегда под килем.","main_image":"яхты над водой и те, кто всегда под килем"},{"title":"Броня для мирного","full_story":"Ночью на поляну выходит панголин: броня из чешуи, ни клыков, ни яда, ни злобы — ужин из муравьёв и деловитый шаг. Хищники пробуют его на зуб и отступают от крепкого шара, а он просто пережидает и идёт дальше по своим делам. К утру поляна снова принадлежит всем, и самый невооружённый её житель остаётся собой. Песня-ирония о том, что самая надёжная броня достаётся тем, кто ни на кого не нападает.","hero_pov":"ночной зверь в чешуйчатой броне","central_conflict":"ночь полна хищников — а у него нет ни клыка, ни злобы","emotional_arc":"от напряжённого ожидания к спокойной неуязвимости","ending_direction":"он сворачивается, пересиживает и встречает рассвет собой","hook_direction":"мирным достаётся броня","genres":["Синтвейв","Электропоп"],"moods":["Ирония","Спокойствие"],"energy":"Средняя","themes":["Ночь","животные","самопринятие"],"generator_brief":"Блестящий синтвейв с шершавым басом: куплеты — ночная поляна и шаги хищников, припев — чешуя-глиттер, финал — рассвет и целая шкура.","generator_story":"Ночью на поляну выходит панголин: броня из чешуи, ни клыка, ни злобы. Хищники пробуют его на зуб и отступают, он сворачивается клубком и встречает рассвет собой.","primary_genre":"Синтвейв","primary_mood":"Ирония","primary_theme":"Ночь","story_shelf":"Люди и животные","conflict_key":"хищная-ночь-против-беззубого-мирного","image_key":"чешуя-блестит-в-лунном-свете","turn_key":"свернулся-и-остался-собой","hook_key":"мирным-достаётся-броня","sort_order":"1447","original_key":"marianne-moore|the-pangolin","author_name":"Марианна Мур","original_title":"The Pangolin","original_language":"английский","origin_country":"США","original_year":"1936","source_url":"http://english.fju.edu.tw/lctd/asp/works/126/text.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1972.","music_adaptations":[],"source_synopsis":"Детально-ироничное стихотворение о панголине: ночном звере в чешуйчатой броне, беззлобном, мирном, при опасности сворачивающемся в шар. Мур любуется его инженерией и сравнивает с людьми — у самых безобидных оказывается самая крепкая защита.","main_image":"ночная чешуя, блестящая как глиттер"},{"title":"Тонкая раковина","full_story":"Смотрительница маяка растит дочь одна: их домик на краю косы тонок, как бумажная раковина аргонавта, — слышно каждый ветер. Штормовой ночью стены ходят ходуном, и они с дочкой сидят посреди комнаты, держась за руки и за шквал сразу. К утру дом стоит: не бетон, а двое внутри сделали его прочным. Песня о том, что крепость — это не толщина стен, а то, кого ты в них держишь.","hero_pov":"смотрительница маяка, мать-одиночка","central_conflict":"тонкие стены домика против шторма всей ночи","emotional_arc":"от страха за хрупкий дом к спокойной силе вдвоём","ending_direction":"шторм уходит — тонкий дом стоит, и это не везение, а забота","hook_direction":"тонкое — не значит слабое","genres":["Эмбиент","Классика"],"moods":["Нежность","Спокойствие"],"energy":"Низкая","themes":["море","семья","дом"],"generator_brief":"Морской эмбиент с шумом прибоя: куплеты — скрип стен и детский вопрос, припев — «мы держим», финал — рассвет над устоявшим домом.","generator_story":"Смотрительница маяка растит дочь одна, и их дом тонок, как раковина. Шторм трясёт стены всю ночь, но к утру дом стоит: двое внутри оказались прочнее камня.","primary_genre":"Эмбиент","primary_mood":"Нежность","primary_theme":"море","story_shelf":"Люди и животные","conflict_key":"тонкие-стены-против-штормовой-ночи","image_key":"дом-на-косе-как-раковина","turn_key":"внутри-прочнее-снаружи","hook_key":"тонкое-не-значит-слабое","sort_order":"1448","original_key":"marianne-moore|the-paper-nautilus","author_name":"Марианна Мур","original_title":"The Paper Nautilus","original_language":"английский","origin_country":"США","original_year":"1941","source_url":"https://poets.org/poem/paper-nautilus","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1972.","music_adaptations":[],"source_synopsis":"Стихотворение о аргонавте — морской улитке, которая вырабатывает тончайшую полупрозрачную раковину-крепость для своего потомства. Хрупкое, сделанное с любовью убежище оказывается прочнее любых гроз — тонкость не значит слабость.","main_image":"полупрозрачная раковина, которую не берёт шторм"},{"title":"Птицы против пил","full_story":"Арендаторы привозят в старый лес мотопилы: план ясен к пятнице, валить под просеку. Лесник и его команда запретить рубку не могут — бумага подписана не ими. Тогда они делают то, что могут: выносят из просеки гнёзда, метят деревья лентами, водят экскурсии, и к выходным под стволами стоит весь посёлок — от школьников до стариков. Рубку переносят. Песня о том, что лес — это чей-то дом, и у дома вдруг находится больше жильцов, чем в бумагах.","hero_pov":"лесник старого леса","central_conflict":"подписанные пилы против вековых гнездовий","emotional_arc":"от бессильного гнева к организованной защите и передышке","ending_direction":"под деревьями весь посёлок — техника разворачивается, лес остаётся","hook_direction":"каждое дерево — чей-то адрес","genres":["Драм-н-бейс","Альтернативный рок"],"moods":["Протест","Решимость"],"energy":"Взрывная","themes":["команда","природа","животные"],"generator_brief":"Драм-н-бейс с ритмом пилы, переходящим в heartbeat: куплеты — маркировка деревьев и гнёзда в руках, припев — посёлок под стволами, финал — отъезжающая техника.","generator_story":"Арендаторы привозят пилы в старый лес. Лесник с командой не могут запретить рубку, но переносят гнёзда и окольцовывают деревья, пока весь посёлок не выходит под стволы.","primary_genre":"Драм-н-бейс","primary_mood":"Протест","primary_theme":"команда","story_shelf":"Люди и животные","conflict_key":"аренда-пил-против-вековых-гнездовий","image_key":"старый-лес-под-мотопилами","turn_key":"посёлок-встал-под-деревья","hook_key":"дерево-это-чей-то-адрес","sort_order":"1449","original_key":"pierre-de-ronsard|contre-les-bucherons-de-la-forest-de-gastine","author_name":"Пьер де Ронсар","original_title":"Contre les bûcherons de la forêt de Gastine","original_language":"французский","origin_country":"Франция","original_year":"1584","source_url":"https://fr.wikisource.org/wiki/Contre_les_bucherons_de_la_forest_de_Gastine","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1585.","music_adaptations":[],"source_synopsis":"Элегия против лесорубов, купивших на раздел старинный Гастинский лес: поэт обращается к лесу как к дому — певчих птиц, оленей, ручьёв — и грозит покупателям и их топорам проклятием. Один из первых в европейской поэзии голосов в защиту живого леса.","main_image":"старый лес, по которому пошли пилы"},{"title":"Сутки на всё","full_story":"Гонщица выходит на суточный марафон и где-то на ночной петле вдруг понимает: это не гонка, это сама жизнь — один заход от рассвета до ночи. Экономить себя на прямых бессмысленно: топливо и так зажжено. Она перестаёт считать круги и начинает проживать их — с полной отдачей, не боясь потратить. Финиш встречает её с горящими фарами. Песня о том, что конечность — не повод ехать на половине.","hero_pov":"гонщица суточного марафона","central_conflict":"старт на рассвете, финиш в ночи — и соблазн сэкономить себя","emotional_arc":"от осторожного расчёта к полной отдаче и свету фар","ending_direction":"она финиширует, потратив всё, — и это победа, даже без кубка","hook_direction":"меньше дня — больше жизни","genres":["EDM","Электропоп"],"moods":["Уверенность","Вдохновение"],"energy":"Высокая","themes":["Дорога","Время","свобода"],"generator_brief":"Восходящее EDM-кидало: куплеты — расчёт и ночная петля, дроп — полная отдача на прямой, финал — свет фар на рассвете.","generator_story":"Гонщица выходит на суточный марафон и понимает: жизнь — одна петля от рассвета до ночи. Она не экономит себя на прямых и финиширует с горящими фарами, успев пожить.","primary_genre":"EDM","primary_mood":"Уверенность","primary_theme":"Дорога","story_shelf":"Трагические истории","conflict_key":"конечная-петля-против-соблазна-экономии","image_key":"фары-на-рассветной-петле","turn_key":"перестаёт-считать-круги","hook_key":"меньше-дня-больше-жизни","sort_order":"1450","original_key":"joachim-du-bellay|si-nostre-vie-est-moins-quune-journee","author_name":"Жоашен дю Белле","original_title":"Si nostre vie est moins qu'une journée","original_language":"французский","origin_country":"Франция","original_year":"1549","source_url":"https://www.poetryintranslation.com/PITBR/French/DuBellayPoems.php","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1560.","music_adaptations":[],"source_synopsis":"Сонет из «Оливы»: если жизнь короче дня перед вечностью и всё рождённое обречено, к чему медлит душа, запертая в теле? Поэт уговаривает её не копить страх, а жить в полную силу отведённого света.","main_image":"петля трассы от рассвета до ночи"},{"title":"Как не стать придворным","full_story":"Молодой поэт берёт уроки успеха у придворного наставника: не читай, льсти нужным людям, держись модной линии, пиши к случаю. Он честно пробует кланяться — и получает свои крохи со стола покровителей. Но одна честная строчка, написанная ночью для себя, уходит в город и возвращается оттуда хором. Финал: наставник сам подходит за автографом. Песня-сатира о том, как рифма перестаёт быть поклоном.","hero_pov":"молодой поэт при дворе пиара","central_conflict":"сарафанное одобрение покровителей против живого голоса улицы","emotional_arc":"от угодливых проб к риску честной строки и победе","ending_direction":"улица подхватывает его строчку — и двор просит автограф","hook_direction":"не кланяйся — рифмуй","genres":["Хип-хоп","Электропоп"],"moods":["Ирония","Уверенность"],"energy":"Высокая","themes":["команда","голос","самоценность"],"generator_brief":"Ироничный хип-хоп с подвохом: куплеты — уроки наставника и первые поклоны, припев — стой прямо и рифмуй, финал — хор улицы и автограф для наставника.","generator_story":"Молодой поэт получает от придворного наставника урок успеха: не читай, льсти, держись моды. Честная строчка уходит в улицу, и наставник сам просит у него автограф.","primary_genre":"Хип-хоп","primary_mood":"Ирония","primary_theme":"команда","story_shelf":"Юмор: семейные драмы","conflict_key":"двор-покровителей-против-улицы","image_key":"поклоны-в-коридорах-и-хор-на-площади","turn_key":"честная-строчка-уходит-в-город","hook_key":"не-кланяйся-рифмуй","sort_order":"1451","original_key":"joachim-du-bellay|le-poete-courtisan","author_name":"Жоашен дю Белле","original_title":"Le Poète courtisan","original_language":"французский","origin_country":"Франция","original_year":"1559","source_url":"https://fr.wikisource.org/wiki/Du_Bellay_-_%C5%92uvres_compl%C3%A8tes,_%C3%A9dition_S%C3%A9ch%C3%A9,_tome_1","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1560.","music_adaptations":[],"source_synopsis":"Ироическая сатира: иронические наставления молодому поэту, желающему успеха при дворе, — не утруждать себя чтением греков и латинян, льстить сильным, писать модные пустяки и держаться поближе к покровителям. Насмешка над превращением поэзии в придворную услугу.","main_image":"коридоры покровителей против открытой улицы"},{"title":"Стук в чужие двери","full_story":"Старый странник ходит по дворам и стучится в чужие двери: платит рассказами о дорогах, которые видел. Чаще всего ему не открывают — но матери открывают всегда: он когда-то говорил с их сыновьями на перекрёстках и знает их судьбы лучше почты. Он приносит им последние вести как подарки и идёт дальше, в ночь. Песня о человеке, чей дом — все калитки, где его ждут, и ни одна не его.","hero_pov":"старый странник на вечерней дороге","central_conflict":"дорога даёт ему голос, но навсегда отбирает собственный дом","emotional_arc":"от чужих запертых дверей к тёплым калиткам матерей","ending_direction":"дверь открывают там, где сын не вернулся, — и он остаётся на ужин","hook_direction":"чужие калитки, где тебя ждут","genres":["Лоу-фай","Фолк"],"moods":["Одиночество","Тепло"],"energy":"Низкая","themes":["дорога","память","голос"],"generator_brief":"Лоу-фай с пыльной гитарой и шелестом гравия: куплеты — запертые калитки и стук, припев — матери на пороге, финал — ужин в чужом доме как награда.","generator_story":"Старый странник стучится в чужие двери и платит рассказами. Матери открывают ему там, где сыновья не вернулись, и он несёт их память дальше по дорогам.","primary_genre":"Лоу-фай","primary_mood":"Одиночество","primary_theme":"дорога","story_shelf":"Трагические истории","conflict_key":"дорога-даёт-голос-отбирает-дом","image_key":"калитки-где-ждут-матери","turn_key":"дверь-открывают-там-где-не-вернулся-сын","hook_key":"калитки-где-тебя-ждут","sort_order":"1452","original_key":"guillaume-apollinaire|le-voyageur","author_name":"Гийом Аполлинер","original_title":"Le Voyageur","original_language":"французский","origin_country":"Франция","original_year":"1913","source_url":"https://lesbonnesfeuilles.fr/bibliotheque/auteurs/guillaume-apollinaire/recueils/alcools/poemes/le-voyageur","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1918.","music_adaptations":[],"source_synopsis":"Стихотворение из «Алкоголей»: фигура странника, который стучится в двери и говорит с жизнью на равных; среди его встреч — игрок, рассказывавший матерям о судьбе их детей. Дорога дает ему голос, но отнимает дом.","main_image":"стук в чужие двери на закате"},{"title":"Билет в одну сторону","full_story":"Эмигрант накануне отплытия в Америку заходит к портному за последним костюмом на этой стороне океана. Пока снимают мерку, он пересказывает портному свою историю любви — улицу, имя, почему обратно пути не будет. Паром уходит в туман, а прощальное письмо так и остаётся в кармане нового пиджака — без адреса, потому что адресат остался в другой жизни. Песня о том, что уехать — не значит доехать, и не всё, что оставляешь, отпускает тебя.","hero_pov":"эмигрант у ночного причала","central_conflict":"океан надежды против улицы, которую оставляешь навсегда","emotional_arc":"от решимости к тишине несбывшегося письма","ending_direction":"паром ушёл — письмо осталось в кармане без адреса","hook_direction":"билет не гарантирует берег","genres":["Блюз","Шансон"],"moods":["Тоска","Меланхолия"],"energy":"Средняя","themes":["Дорога","расставание","письмо"],"generator_brief":"Портовый блюз с аккордеоном: куплеты — портной и мерка, припев — паром и туман, финал — пустой карман с несбывшимся письмом.","generator_story":"Эмигрант перед отплытием в Америку заходит к портному за последним костюмом. Он клянётся не возвращаться; пароход уходит, и письмо с прощанием остаётся без адреса.","primary_genre":"Блюз","primary_mood":"Тоска","primary_theme":"Дорога","story_shelf":"Трагические истории","conflict_key":"океан-против-оставленной-улицы","image_key":"паром-в-тумане-и-письмо-в-кармане","turn_key":"письмо-остаётся-без-адреса","hook_key":"билет-не-гарантирует-берег","sort_order":"1453","original_key":"guillaume-apollinaire|lemigrant-de-landor-road","author_name":"Гийом Аполлинер","original_title":"L'Émigrant de Landor Road","original_language":"французский","origin_country":"Франция","original_year":"1913","source_url":"https://www.poetica.fr/poeme-50/apollinaire-emigrant-de-landor-road","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1918.","music_adaptations":[],"source_synopsis":"Повествовательное стихотворение из «Алкоголей»: перед отплытием в Америку эмигрант заходит на улицу Ландор-роуд к портному за прощальным костюмом и рассказывает свою историю любви, которая не сложилась. Это история билета в одну сторону — и всех вещей, которые пришлось оставить.","main_image":"паром у ночного причала и не отправленное письмо"},{"title":"Голос без розетки","full_story":"Уличная певица с потёртой колонкой поёт на сельском празднике: вокруг — карусели, попрошайки, пьяные споры, и её баллады тонут в громе балаганов. К вечеру праздник накрывает отключка света: карусели встают, сцены гаснут. Её голос без микрофона доходит до конца тёмной площади — и площадь подтягивает. Песня о живом голосе, который не зависит от розетки и всегда допоёт.","hero_pov":"уличная певица на сельском празднике","central_conflict":"ярмарочный гул против одного живого голоса","emotional_arc":"от заглушённости к тишине, в которой слышно каждого","ending_direction":"свет гаснет — голос остаётся, и площадь поёт с ним","hook_direction":"без розетки поёт только живое","genres":["Шансон","Фолк"],"moods":["Драйв","Ирония"],"energy":"Высокая","themes":["дорога","голос","сцена"],"generator_brief":"Ярмарочный шансон с аккордеоном и трещотками: куплеты — гул балаганов и хриплый голос, припев — баллада, финал — тёмная площадь поёт без электричества.","generator_story":"Уличная певица поёт на сельском празднике среди смеха и попрошаек. Когда отключают свет, её голос без микрофона доходит до конца площади, и площадь поёт с ней.","primary_genre":"Шансон","primary_mood":"Драйв","primary_theme":"дорога","story_shelf":"Трагические истории","conflict_key":"ярмарочный-гул-против-живого-голоса","image_key":"тёмная-площадь-и-один-голос","turn_key":"отключка-освобождает-голос","hook_key":"без-розетки-поёт-живое","sort_order":"1454","original_key":"tristan-corbiere|la-rapsode-foraine-et-le-pardon-de-sainte-anne","author_name":"Тристан Корбьер","original_title":"La Rapsode foraine et le pardon de Sainte-Anne","original_language":"французский","origin_country":"Франция","original_year":"1873","source_url":"https://gallica.bnf.fr/ark:/12148/bpt6k1525477d.texteImage","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1875.","music_adaptations":[],"source_synopsis":"Монолог уличной певицы на бретонском церковном празднике: между попрошайками, паломниками и балаганами она тянет свои баллады хриплым голосом, мешая площадной брань с высокой тоской. Корбьер отдаёт ей главную роль — поэт здесь только записывает чужой голос.","main_image":"площадь праздника, где один голос без микрофона"},{"title":"Последний автомат на маршруте","full_story":"Настройщик музыкальных автоматов объезжает бары по своему маршруту: везде плейлисты, автомат стоит в углу накрытый, как бюст ушедшего композитора. В последнем баре маршрута, перед закрытием, он решает не сдавать агрегат в утиль — заводит пружину на всю длину. Пустой зал встаёт в танец, как двадцать лет назад, и барчик оживает на один вечер. Песня о механической петле, в которой осталась человеческая душа.","hero_pov":"настройщик музыкальных автоматов","central_conflict":"цифровой век списал механическую петлю — а она ещё играет","emotional_arc":"от рутинной грусти к ожившему танцу и выбору сохранить","ending_direction":"автомат не в утиль: бар танцует, и маршрут продолжается","hook_direction":"заведи — и оживёт","genres":["Техно","Лоу-фай"],"moods":["Ирония","Тепло"],"energy":"Средняя","themes":["дорога","музыка","работа"],"generator_brief":"Техно из звуков пружины и валика: куплеты — маршрут накрытых автоматов, дроп — заведённая петля, финал — танцующий пустой бар.","generator_story":"Настройщик музыкальных автоматов объезжает бары, где петли сдались плейлистам. В последнем баре он заводит свой автомат, и пустой зал танцует, как прежде.","primary_genre":"Техно","primary_mood":"Ирония","primary_theme":"дорога","story_shelf":"Юмор: семейные драмы","conflict_key":"плейлисты-против-механической-петли","image_key":"накрытый-автомат-в-углу-бара","turn_key":"пружина-заведена-на-всю-длину","hook_key":"заведи-и-оживёт","sort_order":"1455","original_key":"jules-laforgue|complainte-de-lorgue-de-barbarie","author_name":"Жюль Лафорг","original_title":"Complainte de l'Orgue de Barbarie","original_language":"французский","origin_country":"Франция","original_year":"1885","source_url":"https://fr.wikisource.org/wiki/Po%C3%A9sies_compl%C3%A8tes_de_Jules_Laforgue/Les_Complaintes/Complainte_de_l%E2%80%99Orgue_de_Barbarie","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1887.","music_adaptations":[],"source_synopsis":"Жалоба шарманки из сборника «Жалобы»: уличный орган крутит свои циничные куплеты под дождём, будто сам поэт — механический ящик с валиком, из которого выпадают насмешки над жизнью и верой. Смех прохожих и мокрый асфальт вместо зала.","main_image":"музыкальный автомат, который заводят на один танец"},{"title":"Экзамен по любви","full_story":"Клавишник ночного клуба готовится к встрече с Коломбиной как к экзамену: конспекты, видеоуроки, шкала признаков, таблица ошибок. Чем больше он учит, тем страшнее становится сам вопрос — и тем смешнее со стороны. Она приходит не на экзамен, а на его ночную импровизацию без бумажек, и конспект летит под стол. Песня о том, что любовь не сдаётся по шпаргалке — она играется.","hero_pov":"клавишник, влюблённый теоретик","central_conflict":"шпаргалки сердца против живой встречи, к которой нельзя подготовиться","emotional_arc":"от страшной подготовки к свободной импровизации","ending_direction":"она приходит на импровизацию — конспект отправляется под стол","hook_direction":"по любви не бывает конспектов","genres":["Синтвейв","Инди-поп"],"moods":["Меланхолия","Ирония"],"energy":"Средняя","themes":["Ночь","любовь","самопринятие"],"generator_brief":"Лунный синтвейв с арпеджио: куплеты — конспекты и страх вопроса, припев — она рядом и смеётся, финал — импровизация без бумажек.","generator_story":"Клавишник готовится к встрече с любимой по конспектам о любви. Она приходит не на экзамен, а на его ночную импровизацию, и конспект летит под стол.","primary_genre":"Синтвейв","primary_mood":"Меланхолия","primary_theme":"Ночь","story_shelf":"Любовные сцены","conflict_key":"шпаргалки-против-живой-встречи","image_key":"лунный-стол-с-конспектами","turn_key":"конспект-летит-под-стол","hook_key":"по-любви-не-бывают-конспектов","sort_order":"1456","original_key":"jules-laforgue|autre-complainte-de-lord-pierrot","author_name":"Жюль Лафорг","original_title":"Autre Complainte de Lord Pierrot","original_language":"французский","origin_country":"Франция","original_year":"1885","source_url":"http://www.unjourunpoeme.fr/poeme/autre-complainte-de-lord-pierrot","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1887.","music_adaptations":[],"source_synopsis":"Лунная жалоба Пьеро: он готовится постичь женщину по шпаргалкам — науке, статистике и чужим признаниям, — а сама встреча всё откладывается. Ироничное самоедство влюблённого теоретика при свете луны.","main_image":"ночной стол, заваленный конспектами о любви"},{"title":"Два причала","full_story":"Грузчик ночного порта и девушка из кают-компании встречают рассвет между двумя причалами: их корабли отходят в разные стороны света — его на север, её на юг. Всю ночь они носят друг другу кофе между кранами и договорами, зная, что к полудню разойдутся. У трапа они покупают один билет на следующий рейс — встретиться через полгода в чужом порту. Песня о любви, которая живёт расписаниями и всё равно не укладывается в них.","hero_pov":"грузчик ночного порта","central_conflict":"два отплытия из одной ночи — и один шанс на общий рейс","emotional_arc":"от лихорадки погрузки к решению не расходиться навсегда","ending_direction":"корабли уходят врозь, но у них уже есть один билет на следующий рейс","hook_direction":"встретимся в следующем порту","genres":["Драм-н-бейс","Электропоп"],"moods":["Эйфория","Романтика"],"energy":"Высокая","themes":["море","любовь","ожидание"],"generator_brief":"Драм-н-бейс с ритмом кранов: куплеты — ночная погрузка и кофе между контейнерами, припев — рассвет и два трапа, финал — общий билет.","generator_story":"Грузчик порта и девушка из кают-компании встречают рассвет между двумя причалами: их корабли уходят врозь. Они берут один билет на следующий рейс — встретиться в новом порту.","primary_genre":"Драм-н-бейс","primary_mood":"Эйфория","primary_theme":"море","story_shelf":"Любовные сцены","conflict_key":"два-отплытия-из-одной-ночи","image_key":"причалы-расходятся-на-рассвете","turn_key":"один-билет-на-следующий-рейс","hook_key":"встретимся-в-следующем-порту","sort_order":"1457","original_key":"emile-verhaeren|le-port","author_name":"Эмиль Верхарн","original_title":"Le Port","original_language":"французский","origin_country":"Бельгия","original_year":"1895","source_url":"https://fr.wikisource.org/wiki/Le_Port_(Verhaeren)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1916.","music_adaptations":[],"source_synopsis":"Стихотворение из «Городов-спрутов»: ночной порт как сердце мира — золото, товары, люди всех рас и языков встречаются на причалах в лихорадочной погрузке. Верхарн видит в этом хаосе и жадность, и мощь, и надежду всех, кто уезжает.","main_image":"два причала, расходящиеся на рассвете"},{"title":"Уголь в котомке","full_story":"После запрета их веры община хранителей огня уходит в подполье: молельню сжигают, старшего уводят, остальным велено забыть пламя и плакать по расписанию. Вождь и девушка, чей отец подписал запрет, собирают выживших и угли из остывшего капища в простые котомки. Через перевалы, малыми группами, огонь доходит до новой долины. Песня о верности общины, которую нельзя ни сжечь, ни подписать указом.","hero_pov":"молодой вождь подпольной общины","central_conflict":"запрет власти против общего пламени, которое нельзя отменить","emotional_arc":"от разгрома к исходу и новому очагу","ending_direction":"капище разрушено — но угли, унесённые в котомках, разжигают новый очаг","hook_direction":"пока несут угли — вера не погасла","genres":["Эпик-рок","Метал"],"moods":["Решимость","Протест"],"energy":"Взрывная","themes":["команда","верность","свобода"],"generator_brief":"Эпик-рок с хором и ударными: куплеты — разгром и угли, припев — переход через перевал, финал — новый очаг в новой долине.","generator_story":"Община хранителей огня уходит в подполье после запрета. Надзиратели рушат молельню, но выжившие уносят угли в котомках, и через перевалы огонь доходит до новой долины.","primary_genre":"Эпик-рок","primary_mood":"Решимость","primary_theme":"команда","story_shelf":"Трагические истории","conflict_key":"запрет-против-общего-пламени","image_key":"угли-в-котомке-через-перевал","turn_key":"живые-уносят-огонь","hook_key":"пока-несут-угли-не-погасли","sort_order":"1458","original_key":"thomas-moore|the-fire-worshippers","author_name":"Томас Мур","original_title":"The Fire-Worshippers","original_language":"английский","origin_country":"Ирландия","original_year":"1817","source_url":"https://en.wikisource.org/wiki/Lalla_Rookh/The_Fire-Worshippers","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1852.","music_adaptations":[],"source_synopsis":"Поэма из «Лаллы Рук»: в Персии, завоёванной эмиром, запретили древнюю веру огнепоклонников. Молодой вождь общины Хафед и Хинда, дочь эмира, любят друг друга на руинах запрета. Капище разрушено, община разбита — но вера уходит с выжившими в горы.","main_image":"уголь из разрушенного капища, унесённый в котомке"},{"title":"Третий дар","full_story":"Стажёрку выгоняют из команды мечты, и она решает вернуть место любым даром. Первый заход — блестящий проект, сделанный в одиночку: красиво, но холодно, отказ. Второй — бессонная жертва, месяц без выходных: жалко, но нет. Третий дар оказывается не её подвигом: она приводит человека, из-за которого когда-то всё рухнуло, — он впервые просит прощения. Дверь открывается. Песня о том, что лучший дар — не твой подвиг, а чужое раскаяние, которое ты донёс.","hero_pov":"стажёрка, изгнанная из команды мечты","central_conflict":"хочу вернуться — но ни подвиг, ни жертва не открывают дверь","emotional_arc":"от гонора достижений к пониманию цены прощения","ending_direction":"третий дар — приведённый раскаявшийся виновник — открывает дверь","hook_direction":"слеза дороже подвига","genres":["EDM","Электропоп"],"moods":["Надежда","Вдохновение"],"energy":"Высокая","themes":["прощение","спасение","команда"],"generator_brief":"Парящий EDM с хоровым падом: куплеты — неудачные дары, билд — третий путь, дроп — открытая дверь и хор прощения.","generator_story":"Стажёрку выгнали из команды мечты, и она ищет дар, за который её вернут. Блестящий проект и бессонная жертва отклонены — пока она не приводит раскаявшегося виновника провала.","primary_genre":"EDM","primary_mood":"Надежда","primary_theme":"прощение","story_shelf":"Трагические истории","conflict_key":"подвиг-жертва-или-прощение","image_key":"три-дара-у-закрытой-двери","turn_key":"слеза-раскаявшегося-дороже-подвига","hook_key":"слеза-дороже-подвига","sort_order":"1459","original_key":"thomas-moore|paradise-and-the-peri","author_name":"Томас Мур","original_title":"Paradise and the Peri","original_language":"английский","origin_country":"Ирландия","original_year":"1817","source_url":"https://en.wikisource.org/wiki/Lalla_Rookh/Paradise_and_the_Peri","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1852.","music_adaptations":[],"source_synopsis":"Поэма-сказка из «Лаллы Рук»: пери изгнана из рая и может вернуться, лишь принеся дар, самый ценный для неба. Капля крови героя и вздох умирающей любви отвергнуты — врата открывает слеза раскаявшегося грешника: прощение дороже подвига.","main_image":"три дара у порога, из которых принята последняя капля"},{"title":"Крик в ночном поле","full_story":"Мальчик просыпается от крика зайца в отцовских силках — тонкого, человеческого, в чёрном поле. Он выходит с фонариком и ходит по траве по кругу, а крик то приближается, то пропадает. На рассвете он находит только пустой силок — поздно. Он молча разбирает все силки в поле, один за другим, пока отец спит. Песня о первой ночи, когда ты слышишь чужую боль и уже не можешь стать прежним.","hero_pov":"сын браконьера в ночном поле","central_conflict":"крик в темноте, к которому не пробраться, и утро, когда уже поздно","emotional_arc":"от паники поиска к пустому силку и решимости","ending_direction":"зверя он не нашёл — но к рассвету в поле не остаётся ни одного силка","hook_direction":"слушай — и разбери все силки","genres":["Драм-н-бейс","Альтернативный рок"],"moods":["Тревога","Боль"],"energy":"Взрывная","themes":["Детство","животные","выбор"],"generator_brief":"Рваный драм-н-бейс с полевой записью травы: куплеты — фонарик и вслушивание, брейк — пропавший крик, дроп — разборка силков на рассвете.","generator_story":"Мальчик ночью слышит крик зайца в отцовских силках и ищет его по тёмному полю. Зверя он не находит — лишь пустой силок на рассвете, и разбирает все силки в поле.","primary_genre":"Драм-н-бейс","primary_mood":"Тревога","primary_theme":"Детство","story_shelf":"Люди и животные","conflict_key":"крик-в-темноте-без-адреса","image_key":"силки-по-всему-полю","turn_key":"пустой-силок-на-рассвете","hook_key":"разбери-все-силки","sort_order":"1460","original_key":"james-stephens|the-snare","author_name":"Джеймс Стивенс","original_title":"The Snare","original_language":"английский","origin_country":"Ирландия","original_year":"1909","source_url":"https://allpoetry.com/The-Snare","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1950.","music_adaptations":[],"source_synopsis":"Короткое стихотворение о ночном поле: рассказчик слышит крик зайца, попавшего в силок, мечется в темноте, но не может найти место. Крик повторяется — и невозможность помочь становится самой песней.","main_image":"ночная трава, в которой спрятан силок"},{"title":"Одалживая осла","full_story":"На исходе лета семья занимает у соседа Керра старого осла: сено вымокнет, если не убрать его сегодня, а туман съел всю дорогу. Осёл идёт по памяти — хомут, оглобли, знакомая колея, — и телега с сеном выплывает из молока прямо к воротам. Вечером семья возвращает осла и платит соседу лучшей охапкой. Песня о простом деле, внутри которого, если всмотреться, живёт маленькое чудо.","hero_pov":"хозяин семьи, одалживающий осла","central_conflict":"туман съел дорогу — а сено нельзя оставить ещё на ночь","emotional_arc":"от тревоги за урожай к тихой радости выполненного дела","ending_direction":"телега выплывает из тумана к воротам — и осёл получает лучшую охапку","hook_direction":"туман помнит дорогу лучше навигатора","genres":["Регги","Фолк"],"moods":["Тепло","Ирония"],"energy":"Средняя","themes":["Дом","животные","работа"],"generator_brief":"Ленивое деревенское регги с губной гармошкой: куплеты — заем осла и сборы, припев — скрип в тумане, финал — охапка для соседского героя.","generator_story":"Семья занимает у соседа осла, чтобы в тумане привезти последнее сено. Дороги в молоке не видно, но осёл идёт по памяти, и вечером ему отдают лучшую охапку.","primary_genre":"Регги","primary_mood":"Тепло","primary_theme":"Дом","story_shelf":"Юмор: семейные драмы","conflict_key":"туман-съел-дорогу-сено-ждёт","image_key":"осёл-с-телегой-в-молочном-тумане","turn_key":"осёл-ведёт-по-памяти","hook_key":"туман-помнит-дорогу","sort_order":"1461","original_key":"patrick-kavanagh|kerrs-ass","author_name":"Патрик Каван","original_title":"Kerr's Ass","original_language":"английский","origin_country":"Ирландия","original_year":"1951","source_url":"https://patrickkavanaghtrust.ie/kerrs-ass","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1967.","music_adaptations":[],"source_synopsis":"Стихотворение о том, как у соседа Керра занимают осла, чтобы в тумане привезти сено. Список упряжи и хомутов, скрип в молочной дымке — и открытие, что бог воображения живёт в самом простом хозяйственном деле.","main_image":"осёл в утреннем тумане с телегой сена"}]$cj$;
  rec jsonb; v_id uuid; n int := 0;
BEGIN
  FOR rec IN SELECT * FROM jsonb_array_elements(c) LOOP
    IF EXISTS (SELECT 1 FROM song_idea_sources WHERE original_key = rec->>'original_key') THEN
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM song_ideas WHERE editorial_status = 'accepted' AND lower(trim(title)) = lower(trim(rec->>'title'))) THEN
      RAISE EXCEPTION 'SYNC DUB title=% (%)', rec->>'title', rec->>'original_key';
    END IF;
    IF EXISTS (SELECT 1 FROM song_ideas WHERE editorial_status = 'accepted' AND (lower(conflict_key) = lower(rec->>'conflict_key') OR lower(image_key) = lower(rec->>'image_key') OR lower(hook_key) = lower(rec->>'hook_key'))) THEN
      RAISE EXCEPTION 'SYNC DUB semantic=%', rec->>'original_key';
    END IF;
    INSERT INTO song_ideas (title, full_story, hero_pov, central_conflict, emotional_arc, ending_direction, hook_direction,
      genres, moods, energy, themes, generator_brief, generator_story, primary_genre, primary_mood, primary_theme,
      story_shelf, conflict_key, image_key, turn_key, hook_key, editorial_status, is_published, sort_order)
    VALUES (
      rec->>'title', rec->>'full_story', rec->>'hero_pov', rec->>'central_conflict', rec->>'emotional_arc',
      rec->>'ending_direction', rec->>'hook_direction',
      ARRAY(SELECT jsonb_array_elements_text(rec->'genres')),
      ARRAY(SELECT jsonb_array_elements_text(rec->'moods')),
      rec->>'energy',
      ARRAY(SELECT jsonb_array_elements_text(rec->'themes')),
      rec->>'generator_brief', rec->>'generator_story',
      rec->>'primary_genre', rec->>'primary_mood', rec->>'primary_theme',
      rec->>'story_shelf', rec->>'conflict_key', rec->>'image_key', rec->>'turn_key', rec->>'hook_key',
      'accepted', false, (rec->>'sort_order')::int)
    RETURNING id INTO v_id;
    INSERT INTO song_idea_sources (idea_id, original_key, author_name, original_title, original_language,
      origin_country, original_year, source_url, rights_check, music_adaptations, source_synopsis, main_image, editorial_status)
    VALUES (v_id, rec->>'original_key', rec->>'author_name', rec->>'original_title', rec->>'original_language',
      nullif(rec->>'origin_country', ''), nullif(rec->>'original_year', '')::int,
      rec->>'source_url', rec->>'rights_check', COALESCE(rec->'music_adaptations', '[]'::jsonb),
      rec->>'source_synopsis', rec->>'main_image', 'accepted');
    UPDATE song_ideas SET is_published = true WHERE id = v_id;
    n := n + 1;
  END LOOP;
  RAISE NOTICE 'SYNC inserted %', n;
END
$sync$;

UPDATE song_ideas
SET is_published = false, editorial_status = 'archived', updated_at = now()
WHERE editorial_status <> 'archived' AND sort_order IN (
  97, 98, 166, 174, 175, 222, 231, 234, 348, 374, 621, 1289, 1026, 1212, 1213, 1217, 1221, 1282, 1285, 1286, 1287, 1288, 1290, 1292, 1293, 1297, 1298, 1303, 1304, 1306, 1310, 1311, 21, 96, 153, 204, 323, 376, 377, 378, 379, 549, 550, 551, 552, 553, 554, 559, 564, 898,
  34, 230, 387, 388, 389, 390, 581, 582, 583, 584, 585, 586, 587, 588, 589, 928, 930, 931, 268, 326, 394, 596, 597, 598, 601, 113, 213, 239, 327, 395, 396, 604, 902, 19, 185, 391, 392, 590, 591, 592, 593, 594, 595, 856, 207, 311, 634, 635, 637, 638,
  938, 100, 1192, 1195, 1196, 1197, 1198, 341, 1199, 1200, 1283, 1308, 1309, 1294, 1219, 1216, 261, 342, 1204, 160, 257, 340, 258, 624, 1205, 279, 626, 627, 145, 245, 630, 631, 87, 99, 103, 111, 112, 116, 125, 127, 143, 156, 177, 199, 203, 210, 228, 235, 237, 302,
  305, 457, 500, 501, 511, 533, 538, 539, 718, 719, 779, 782, 842, 843, 878, 909, 974, 1011, 1049, 1066, 1097, 1098, 1099, 1100, 1101, 1120, 1121, 1132, 1372
